/* 平成17年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h17.committeeSessions.push(...[{"id":"h17-20051129-8","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"建設委員会","time":"午前１０時０４分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","agenda":"平成１７年請願第５号 投資用ワンルームマンション建設計画地の公園化に関する請願","exchanges":[{"speaker":"林（和）委員","kind":"質問・要望","question":"今の説明にございましたけれども、前回の９月２６日に第１回の審査を行いまして、そのときには相当の時間、審議をさせていただいたわけですけれども、１回目だからいきなり結論を出すというのかどうかということで、そのときには継続という状況でございました。その建築についても、本体を含む会社自体もまだ決まっていないような状況ということで、やる会社がいないんじゃないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-001"},{"speaker":"土井委員","kind":"質問","question":"現地を見せていただいたりお話を伺ったりさせていただいて、紹介議員である林委員のお話があったんですけれども、今までの状況等を勘案いたしますと、状況にあまり変化がない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-002"},{"speaker":"菊地委員","kind":"質問・要望","question":"課長の説明のところでは、私は聞きとれなかったんですけれども、今、土井委員が言われた、地裁での中身をもう少しよく教えていただきたいんですけれども。","respondent":"浜脇住宅課長","answer":"建築主の方から私道の上の方の中央に住民がポールを設置したのに対して、東京地裁に妨害排除仮処分の申請をしたということで、その審議の内容についてはつかんでございません。","voiceIndex":8,"id":"exchange-003"},{"speaker":"菊地委員","kind":"質問","question":"住民の皆さんが立てたポールに対して事業主がということなんですね。わかりました。そうすると、こういう場合の地裁での決定にどれぐらいかかるのか、私もよくわからないんですけれども、じゃあ、実際に地裁での結論が出ると予想される期間というのはどれぐらいなんですか。","respondent":"浜脇住宅課長","answer":"今回の場合、ちょっとわかりません。","voiceIndex":10,"id":"exchange-004"},{"speaker":"菊地委員","kind":"質問","question":"裁判ですとか、あるいはそれに類する問題が起きた場合には、土井委員が言われるように、どうしてもその場で結論を出すというのは難しくなるのかなと思いますけれども、どちらにしても、私は前回の委員会のときも申し上げましたけど、地上５階、地下３階というふうに言いますけど、現実的には８階建ての建物であるといえば、これはもうどこから見ても明確なわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-005"},{"speaker":"井上委員","kind":"質問","question":"ですから、そういうふうなことも視野に入れて、「公園ではない」というようなことではない考え方も、ひとつできるのではないかということで、ぜひ、結果を出すということで進めてほしいというのが意見で、もう一つ、その建物に対しても、地域の皆さんの心配もわかりますので、結果を出すという方向でまとめていただければと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-006"},{"speaker":"堺委員","kind":"意見","question":"ただ、今の課長のご説明によりますと、２６日の委員会以降、なかなかいい形での状況の変化がないという中にあって、東京地裁で係争中というご報告もございましたので、委員会としてはなるべくこの種の請願・陳情等については、早い時期に結論を出してあげた方がいいのかなという気がいたしますが、ただ、係争中ということでもありますので、できればその決着が出た段階で。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":14,"id":"exchange-007"},{"speaker":"大西副委員長","kind":"意見","question":"先ほど課長の話の中で、１１月１日以降に事を慎重にするようにということで、その辺のところをもう少しわかりやすく話していただけますか。どういう趣旨なのかがよくわからなかったので、最後の部分をご説明願います。","respondent":"浜脇住宅課長","answer":"解体工事に着手したいということで、当初、１０月２０日、２１日に説明に回りまして、それ以降、１１月２２日以降、説明に当たっているということです。","voiceIndex":15,"id":"exchange-008"},{"speaker":"大西副委員長","kind":"意見","question":"私、個人的な感覚としては、今、裁判係争中ということが出ましたけれども、この裁判の係争の案件と、このマンション建設に関する案件は別個の問題だと思うんですね。住民の方々としても、大変不安なものをずっと引きずるような状態にもなろうかと思いますので、皆さんの意見の中に少しありました、裁判の係争中ということは別個としてとらえてもいいんではないか。これは、私の個人的な考え方です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":17,"id":"exchange-009"},{"speaker":"土井委員","kind":"意見","question":"要するに、８階建てが建てられるということに対する問題と、公園化の問題と、そこら辺を、もしもいろいろ決定するにつけても、その部分を我々としてしっかり議論しておかないと、無茶な形になったみたいに、期待が高まって、現実がともなわないという話になっては困りますので、その辺を含めると私は、もう少し議論を含めて推移を見た方がいいという判断をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-010"},{"speaker":"林（和）委員","kind":"質問・要望","question":"もっと勉強をといっても、９月からというと、１０、１１、もう２カ月たっているわけですから、その間に各自勉強されたと思いますので、そういう意味で９月２６日は継続審議になっているわけですから、本来ならばそのときに結論を出してあげた方がよかったなと思ったんですけれども、とにかくそれじゃ早過ぎるということで、それで今回に伸ばしているわけですから、できれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":20,"id":"exchange-011"},{"speaker":"菊地委員","kind":"意見","question":"前回、初めての審査の際に、これを採択すべきだという立場で主張しましたけれども、もし、今、堺委員や林和也委員が言われたように、結論を出すという方向であれば、私自身はこの請願について採択を主張するという立場ですので、今、どっちかというと３対３で分かれているという形になりますけれども、紹介議員である林和也委員の主張のとおり採択をするという方向であっても、私の方は構わないという立場を。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-012"},{"speaker":"大西副委員長","kind":"質問","question":"ほかの部分を持ってきてですね。その辺のところを、私どもとしてはもう少し話し合う必要性、議論の余地が残っているんじゃないか。本旨の部分にはそんなに差はないかもしれないけれども、利用とか、そういう面に関しましては、もう少し議論を慎重にしなきゃいけないんじゃないかというふうに、感じとしては持っております。最初の質問のときには、原則では継続が望ましいのかなと言っていますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-013"},{"speaker":"堺委員","kind":"質問・要望","question":"今の委員長のご発言でちょっと感じるんですが、前回の委員会のときにもご説明をいただいて、それなりに私もメモってあるんですが、間違えるといけませんので、念のためもう一度確認をする意味で質問してよろしいでしょうか。２点。仮に建築確認の申請書が出れば、その当該地については、梶原氏の館として発掘調査が必要になってくる。それも私、ちょっとメモってあるんですが、それをすみませんがもう１回。","respondent":"岩田まちづくり事業部次長","answer":"もし、公園として区が買うとなった場合でも、地域住民の方のために買うという見方も一方でできますし、もう一方、反対の見方をしますと、着手しようにもできない業者、施工主を、逆に言えば処分に困った土地を行政が買うということで、逆に租税を投じた業者の救済に当たる。","voiceIndex":25,"id":"exchange-014"},{"speaker":"堺委員","kind":"確認","question":"そうすると、前回の説明の中で、事業主の建築確認の申請書は出ているということでしょうか。","respondent":"浜脇住宅課長","answer":"先ほども申し上げましたけれども、１０月１９日に確認申請を、品川区の建築主事が受けつけています。まだ審査中であります。","voiceIndex":27,"id":"exchange-015"},{"speaker":"堺委員","kind":"確認","question":"１０月１９日に区に申請して、現在審査中。そうすると、さっきの建築確認の申請が出れば、事業主が当該地を試掘するという。だから、まだ審査中だから試掘はしない。審査が終わった段階で試掘に入るんですか。さっきの次長の説明から考えていくと、当該地はそういうところだから、事業主が当該地を取得しなければいけないわけでしょう。その辺の手順はどうなっていますか。","respondent":"岩田まちづくり事業部次長","answer":"建築確認そのものは、新たに建物を建ててもよろしいですよということですので、現在は、それ以前として、まず建物の解体をして整地をするという工事については、特に許可を持ってやるというものではございませんので、私どもは。","voiceIndex":29,"id":"exchange-016"},{"speaker":"堺委員","kind":"確認","question":"それが必要な場所ではないんですよ。解体工事の説明をして了解を得られたら解体をして、さっきの梶原氏の館というのは、試掘ということを一つもしないで、解体して更地にして、建築確認申請書を受理されるかといったら、そういういうことではないだろうと思うんです。私個人はそのように思います。","respondent":"岩田まちづくり事業部次長","answer":"私どもが今、業者から聞いておりますのは、まず建物を解体し、建物を除去した後に土地の試掘を行う。","voiceIndex":31,"id":"exchange-017"},{"speaker":"堺委員","kind":"質問","question":"逆に、試掘調査をして、本調査をして、ここは歴史的にもあるいは教育的にも保存する場所ですと東京都が認定をしたという表現になるのかわかりませんが、そうなった段階で、東京都がお金を出して、それにふさわしい整備をしなさいという形になってくるということですか。","respondent":"岩田まちづくり事業部次長","answer":"ケースとすれば、区が買い取って、文化財として保存するという方法もありますし、あるいは地主の方が別の方法として保存する方法をお考えになるかもしれませんが、それはいろいろケースバイケースですので、今の段階では、この場合どうだということは。","voiceIndex":35,"id":"exchange-018"},{"speaker":"堺委員","kind":"質問","question":"その段階では、地主さんの意向というのが非常に大きなウェイトを占めてくるんですか。そのようなときに教育委員会が、せっかくこういうことで試掘して本調査して、ここは保存したいという思いが仮にあるとすると、地主さんが「私はこうやります」とか、あるいは「そこまでしてやりません」という地主さんの思いの方が、結論を出すに当たっては比重が大きいということですが、それはどうなんですか。","respondent":"岩田まちづくり事業部次長","answer":"保存すべきかどうかというのは、教育委員会が決定をいたします。行政がですね。それで保存すべきとなれば、これは法律上、地主であろうと、それを破壊、あるいは変更という行為は禁止をされます。したがって、地主の方であろうと、遺跡については一切触れられなくなります。","voiceIndex":37,"id":"exchange-019"},{"speaker":"堺委員","kind":"質問","question":"私もそうだろうと思うんですが。ですから、その辺のところは、素人判断としては、試掘して本調査に入らないとここで言われていることは、そのときに調査をしなくちゃわからないということですから、仮にそうだということが断言できるとなれば、そこまできちっとやらない限りわからないということかなという気がするんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-020"},{"speaker":"堺委員","kind":"質問・要望","question":"この種の請願については、いろいろあるかと思いますが、所管の方でも、ぜひひとつ近隣の方々の意向を受けて、事業者の方に誠意ある対応をするように行政指導をしていただきたいです。されているかとは思いますが、念のため、行政の方にしかるべき行政指導を重ねて強力にお願いしていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-021"}]},{"id":"topic-02","title":"の水上バス運行便数の変更","agenda":"の水上バス運行便数の変更","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"年間８万６,０００人の利用者があったのが、昨年度は３万１,０００人にまで落ち込んだということですけれども、これはどういうことか、何か原因があったんですか。わかりませんか。","respondent":"藤田道路公園課長","answer":"水族館の利用の減少というようなことも若干はあろうかと思いますが、大きくは、この航路に限る話ではなく、水上バス全体のご利用の方が減ってきているということで、水上バスというような形での運行が大変厳しい状態だということで、見直しを図りたいということです。","voiceIndex":47,"id":"exchange-022"},{"speaker":"林（和）委員","kind":"質問","question":"水上バスの利用者が少なくなったというのは、何か原因があったんでしょうか。","respondent":"藤田道路公園課長","answer":"私ども、確認している中では、海の上を走るということで、さまざまなメリットもあろうかと思いますが、東京の中の交通ですので、鉄道等の便利さと比べて、時間もかかるというようなこともございまして、伸び悩んで、若干落ち込んでということと確認しています。","voiceIndex":49,"id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"そうすると、水族館のＰＲも当然必要なんだけれども、水上バスも含めたＰＲ等もやっていただく中で、これ自体の認知度を上げないと、あまりご存じないというほうが多いんじゃないかなと、そんな気がしてならないので、その点、水上バスを運行している皆さんにもお願いしなきゃいけないし、水族館の方でも、もしくは区でも、その辺について育てていかなきゃいけない部分があるんじゃないかと思いますので。","respondent":"藤田道路公園課長","answer":"ただ、だからといって、１便を減らせばそれでいいんだということではなくて、お互いに、水上バスだけではなく、水族館、あるいは区とあわせる中で、お互いにもう少し何とか工夫ができないのか、そういうことをこれから一生懸命考えていこうよということで投げかけてあります。","voiceIndex":51,"id":"exchange-024"}]},{"id":"topic-03","title":"ます。 ──────────────────────────────────────────── (2) 戸越幹線貯留管整備工事その３の着手について 次に","agenda":"ます。 ──────────────────────────────────────────── (2) 戸越幹線貯留管整備工事その３の着手について 次に","exchanges":[{"speaker":"林（和）委員","kind":"質問","question":"工事その１、それからその２、その３が、完成するのが１９年２月の予定になっているわけですけれども、これができた時点では、雨量の何ミリ対応というか、それはどうなんですか。","respondent":"原田下水道河川課長","answer":"現状でも５０ミリなんですが、工事が終った後に雨水の水道水に入ってくる量が、以前は５０％と設定させていただいていたんですが、今は８０％ということで、能力不足だということで、その能力不足を補うためにこの貯水管をつくっているところでありまして、５０ミリ対応だです。","voiceIndex":56,"id":"exchange-025"}]},{"id":"topic-04","title":"東急大井町線旗の台駅改良工事","agenda":"東急大井町線旗の台駅改良工事","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"今回の旗の台の場合は、急行の乗り入れに合わせて駅を改良して、エレベーター、エスカレーターを設置するということなんですけれども、その旗の台の駅は関係ないんですけれども、大井町線、まだ幾つか、エレベーター、それからエスカレーターが全く設置されていないという駅もありますけれども、全体がこう進んでいくんでしょうか。","respondent":"阿部都市計画課長","answer":"ただ、東急の方からは、いつの時点で、下神明駅についてやるかという返事は来てございませんけれども、一応、今申し上げたとおり、２０１０年ということになっていますので、申し入れはしています。","voiceIndex":62,"id":"exchange-026"},{"speaker":"菊地委員","kind":"質問","question":"今の下神明駅の件で、土地がないとつけられないみたいな話も聞いているんですけれども、その辺、 の申し入れをしていくということで理解していいですか。わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-027"},{"speaker":"井上委員","kind":"質問","question":"今、東急線で、大井町駅から旗の台の心身障害者福祉会館に車いすを利用した人が行く場合に、東急から乗っていって、東急の先の洗足駅のホームの反対側に乗って、戻ってきて出ないと身障者会館にスロープを通って出られないということで、大井町駅からの方たちは皆さんそういうことで旗の台の身障者会館に行っているんですけど、これでできることになるんですか。","respondent":"阿部都市計画課長","answer":"下の切りかえ後というのをごらんいただきますと、大井町から二子玉川に行くほうですので、下り線のところにエレベーターを設置しますので、そうしますと、ここをおりていただいて、新南口、これが身障者会館に行けますので、行けるようになります。","voiceIndex":65,"id":"exchange-028"},{"speaker":"堺委員","kind":"質問","question":"大井町線の駅の、区役所に一番近いところが一番危ないということなので、２０１０年までの間には何とかしてくれるのかなとは思いますが、地元の一人としては、１日でも早くあそこを何とかしてほしいという、地元の町会長さんをはじめ、多くの方々の願いでもありますので、その辺ひとつ、ぜひご努力をお願いしたいと、重ねてこの件についてはお願いしておきたいと思います。私の記憶にはないんですがね。","respondent":"阿部都市計画課長","answer":"区有地ですと、今、委員おっしゃったように、身障者会館は区の施設ですね。りぼん、その近辺ですね。保育園があります。","voiceIndex":67,"id":"exchange-029"},{"speaker":"堺委員","kind":"質問","question":"今、お話があった３カ所以外に、もっと駅に近接しているというか、そういう区有地はないんですかね。","respondent":"阿部都市計画課長","answer":"今、申し上げた４カ所ぐらいの施設だと思います。","voiceIndex":69,"id":"exchange-030"},{"speaker":"土井委員","kind":"意見","question":"急行停車の問題ですとか、バリアフリーの問題とかいろいろな課題があって、解決をするためにいろいろ考えていることになっているんですが、これのお金の関係は、どういう形になっているのか、ちょっと説明いただけますか。東急が全部出してやることなのか、都や国や区が地元も含めてやっているのか。","respondent":"阿部都市計画課長","answer":"基本的には、急行の問題がありますので東急が負担をして、駅舎改良をしているということになります。","voiceIndex":71,"id":"exchange-031"},{"speaker":"菊地委員","kind":"質問","question":"急行の乗り入れで、１日の乗降客、現状とどの程度変わっていくのかというのと、大きく変わるんであれば、駐輪場の問題とか出てくるのかなと思うんですけれども、そこだけ教えてください。","respondent":"阿部都市計画課長","answer":"退避可能な施設にするという話ですので、それに伴ってどう増えるかという話は、まだ明確になってございません。駐輪場の話につきましては、区としては、東急を利用する中で、駐車場は用意していますし、東急としてもそういうことだと認識しています。","voiceIndex":73,"id":"exchange-032"},{"speaker":"土井委員","kind":"質問","question":"質問というよりも、当然文教委員会での議論があるわけですので、そちらにゆだねなきゃならないものだろうと思いますが、私どもの会派でもいろいろ議論いたしまして、小学校建替え、いわゆるまちづくりの観点の部分も入らないということはない、これは当然わかっているわけですけれども、とは言っても、教育の場でありますから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-033"},{"speaker":"井上委員","kind":"質問・要望","question":"今のところに関連するかと思うんですけれども、この計画について、学校そのものではなく、教育委員会とまちづくり事業部との協議の中で、この学校改築計画というというのはどういう関係で出されていったのか。要するに、再開発のこういった部分があって出てきたものなのか、そういうところで、知り得る情報だけで結構ですので、お知らせいただきたいと思います。","respondent":"上野都市開発課長","answer":"お手元、資料のところの、御殿山小学校そのものが築４５年ほどたって、近い将来建替え時期を迎えるという現状があるということと、その周辺の開発動向として、隣接する南側の地区で。","voiceIndex":84,"id":"exchange-034"},{"speaker":"井上委員","kind":"質問","question":"今の、都からの投げかけという時期はいつだったのか教えていただけますでしょうか。","respondent":"上野都市開発課長","answer":"地元再開発準備組合の方で、計画に関する協議をこれまで進めてきましたけれども、その協議の中で前々から示されていたということです。大体いつということですけれども、過去数年間の協議の中で、そういう話が出てきたです。","voiceIndex":86,"id":"exchange-035"},{"speaker":"井上委員","kind":"質問","question":"投げかけられたということは、多分そういうふうな都からの何かがあったと思うんですが、そこのところをもうちょっと詳しく、アバウトでなくて、「ここです」ということで教えていただけますか。","respondent":"上野都市開発課長","answer":"この道路を整備することに関して、地区計画で周辺の一体的な整備を図るかどうかにつきましては、平成８年以降、平成９年に、北品川五丁目再開発準備組合が設立されて、それから計画内容がある程度検討に着手された段階から、東京都と都市計画決定に向けて協議を進めてきまして。","voiceIndex":88,"id":"exchange-036"},{"speaker":"菊地委員","kind":"質問","question":"今、該当区域の道路の話だけがありましたけれども、図面上で見れば、もし高層建築物が建ち上がってくれば、御殿山小学校そのものは、また日影になっていく状況だと思うんですけれども、現状、来年度には都市計画決定を予定しているとのことですから、一定程度のことはでき上がっているんだと思いますけれども、そこだけちょっと教えていただけますか。","respondent":"上野都市開発課長","answer":"再開発の計画を検討するに当たって、その前提となる範囲というか、土俵を決めるために、御殿山小学校の建替え方針を定めたということですから、これを計画の前提として、この組合の方で計画の詳細の検討を進めるということになってありますので、検討が進みしだい。","voiceIndex":90,"id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3838#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":20097,"voices":92}},{"id":"h17-20051129-9","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"文教委員会","time":"午前１０時０４分～午後０時１９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を16件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"御殿山小学校の建替え","agenda":"御殿山小学校の建替え","exchanges":[{"speaker":"山村委員","kind":"質問","question":"もともと日野学園は、確かに子どもがこれから本当に増えるのなら、こういう偏重した増え方というのはいいのかもしれないですけれども、少し、僕は余りこの御殿山小学校は、ある意味、改築しなくてもいいような気もしないでもないなと思って、場所的なことを考えると、ちょっとどうしても日野学園と近過ぎるということ、あと、この地域はそういう意味では新しい小学校は日野学園ができたわけですから。","respondent":"市川庶務課長","answer":"日野学園と、この御殿山小学校の距離的な関係からいって、両立はするのかということについては、これは私ども教育委員会もそうですけれども、御殿山小学校の経営方針そのものが、品川区が小中一貫教育をこれから進めていく中でも。","voiceIndex":7,"id":"exchange-001"},{"speaker":"山村委員","kind":"質問・要望","question":"御殿山小学校の建替えがある。本当に日野学園があった場合、この地域で小学校が要るか、要らないかというのはすごく微妙な地域だと思うので、またこの地域の周辺というのは、若い人が来れるような地域ではあんまりないし、土地の値段的に考えて、はっきり言って土地が高い地域ですから、そんなに子供がいる層が来る地域じゃないと思いますよ、あそこの地域は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問","question":"１０年ぐらい前になるのかな、御殿山小学校の体育館の改築計画が一度発表されて、途中でそれが引っ込んじゃって、なぜ引っ込んだんだと言ったら、開発絡みだという説明がかなり前に一度あったんですけれども、今度のこの計画では、開発地区から除外をしたというのは、これはこれでいいんですけれども、ここの中で書いてある「再開発事業と連動し」という、この「連動し」という意味はどういう意味なんですか。","respondent":"市川庶務課長","answer":"ということは、私どもの敷地の使い方そのものについて影響が出るわけでして、これは、今、品川区立の小学校と幼稚園が建っているわけですけれども、これが仮に任地であっても、これは都市計画サイドからすれば、同様にこの計画道路と再開発区域の間の土地の動向が。","voiceIndex":10,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問・要望","question":"私の２人の娘が御殿山小学校を卒業させていただいて、そこは本当に緑に囲まれた、今日行った立会小学校と同じようないい環境にあるだけに、これは太陽を奪われるというようなことにならないように、区教育委員会としてもなかなか厳しい立場だというのはわかりますけれども、ぜひ子供たちのそういう環境を守るために頑張っていただきたいなというふうに思うんですが、現時点で、何かそういう建築計画。","respondent":"市川庶務課長","answer":"事業主体です再開発準備組合のほうで、正式な意思決定は今後され、しかるべき時期に区議会のほうにも報告されるということは先ほども申し上げたとおりなんですが、当然のことながら、私どもが御殿山小学校建替えの方針決定をするに当たりましては。","voiceIndex":12,"id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"ところが、我々がそれを見せてほしいと言うと見せない。そういう意味では、もしあるならば、その模型を文教委員会でぜひ早い段階で、今、町会関係者や開発者には見せるけれども、それ以外の人には見せないというのでは、全然本末転倒していると思うので、ぜひ教育委員会のほうでも、早く状況をつかんでしかるべきものを、文教委員会でもあるならば見せてほしいということをぜひ要請したいと思います。","respondent":"市川庶務課長","answer":"これは東京都の決定です。その上で、平成２０年度工事着工、２３年度竣工です。２点目の点については、私どももちょっと承知していない部分があります。ただ、今後の経過の中で、そういった資料をお示しできるものが出てくれば、考えさせていただきたいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"松澤委員","kind":"質問","question":"そうすると２４年。今から７年先の話ですよね。その中で本当に、今、小中一貫校日野学園ができて、募集を見てもあれだけ集まって抽選しなくちゃいけないという中で、果たして７年間の時代の変化の中でどうなるんだ、その先行きを見ないで、今、建替えの計画をするなんて、僕は間違っていると思うんですよ。その辺の子供たちの予想とか、そんなものは考えているんですか。","respondent":"市川庶務課長","answer":"これはやはり、いろいろなことというか、日野学園の影響もあると思うんです。ただ、今、推計している２３年度までは、進学児童の推計といたしましては、これまでの平均的な数値の推移というのを同様に見込めるということが一つあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"松澤委員","kind":"意見","question":"御殿山小学校と第二日野小学校の関係は、常に第二日野小学校がなくなる、なくなるといううわさの中で御殿山小学校に集まっているということが、私は感じがあると思っているんです。実際に、これが竣工して、できて７年後にどうしようかというときに考える場合に、ここで建替え計画することはどうも拙速のような気がします。","respondent":"古川教育次長","answer":"ちょっと補足のご説明をさせていただきたいんですが、基本的に建替えの方針は先ほどご説明申し上げたとおり、再開発の動きと合わせた御殿山小学校の将来像ということなんですが、松澤委員、山村委員からもご指摘されていますが、御殿山小学校の将来像はどう考えているか。","voiceIndex":18,"id":"exchange-007"},{"speaker":"松澤委員","kind":"質問","question":"校長と話しましたが、すごくやる気があって、私たちは御殿山小学校を頑張るんだよという話を聞いたんですけれども、あの校長もあと１年、来年かな、ですよね。それはいかがなんでしょうか。","respondent":"市川庶務課長","answer":"ただ当然のことながら、隣接する私どもの敷地が関係することですので、その関係では、環境整備と申しましょうか、そういったところでは、再開発事業の一環として、例えば整備とか、そういったものは当然のことながら出てくるものだというふうに見込んでおります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"沢田委員","kind":"提案","question":"今日、総務委員会のほうで、総合体育館の移転した後の利用をどうするのかというような報告があるというのは昨日聞いたんですよね。今度のこの学校についても、結局、開発で道路を削られるから、この際だから一緒に学校改築を。超高層が何本も建っている。だから、私はどうもこの提案は割り切れないということだけ、質問ではないですよ、意見だけ述べさせていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":22,"id":"exchange-009"},{"speaker":"山村委員","kind":"質問","question":"ちょっと常々思っていたことなんですけれども、学校を全部維持していますが、あまり、本当は言っていいかどうかわからないんですけれども、学校というのも数をある程度間引きしていくという言い方は変ですけれども、していったほうが、逆に１校１校にかけるお金というのは多く使えるものじゃないんですかと思ったりするんです。意見にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"若林委員","kind":"提案","question":"ハード面では、幹線道路になります環境面、または交通安全、それから決算特別委員会でも私の会派のほうからもちょっとご提案といいますか、あったかと思いますけれども、いわゆる小学校の建物、教室の高さが今までは３ｍという基準がありましたけれども、この時期に来て、政府のほうも２.７ｍという見解もありますので、ぜひそこら辺のハード面の部分もぜひ考えながらお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"だから、子どもたちが少なくなってしまう。そういうときに、学校に非常に空き教室が広がって、あるいは希望数が少なくなって、そして統廃合という率直なご意見も出ていますよね。要望も含めて、ちょっとその辺の見解というのをちょっと言っていただきたいと思います。","respondent":"市川庶務課長","answer":"ご質問の前提とされた、先ほど私が松澤委員からいただいたご質問に説明させていただいた今後の１年生の推計値、これは今後建つであろうマンションというものは一切見込んでございません。","voiceIndex":25,"id":"exchange-012"},{"speaker":"西本委員","kind":"質問","question":"土地のある程度いろいろなところを整備しなきゃいけないということで、延びる可能性もあると思うんですけど、小学校の場合には、たとえ決まった場合には、それとはまた別個で進めることはできないんでしょうか。学校が先に建っているとか、ここ一帯につくるということになるので、学校を先に建てるということはできないんでしょうか。７年かかっちゃうんでしょうか。","respondent":"市川庶務課長","answer":"今回、建替えの方針を決定させていただいた方針というのは、今後の再開発事業の具体的な事業展開、具体的な計画を明らかにされて、具体的な事業予定、事業日程が示されてまいるわけですけれども、それといかに交差していくかということを判断していく必要があると考えています。","voiceIndex":27,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、私は７年間の動向、８年間の動向があると思うんですが、周りの環境を見ながら、建築を進めていかざるを得なくなるんじゃないかというふうに感じます。保育園もなかなか入れなくて、大変な思いを皆さんされているという現状を考えると、その辺はしっかり見ていただいて、計画を立てていただきたいというふうに要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-014"},{"speaker":"西本委員","kind":"意見","question":"ボランティアの人たちのお話を聞きたいんです。ボランティアの保護者の方たちの説明が９時からあるので、それの動きを見ないと、他のどういう動きというところ、全体像が見えなくなっちゃうと思うんですよね。ですので、私は希望して９時から。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"私、先に行っていいですか。そういう形で、別行動じゃなくて。９時から行かせてもらって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":62,"id":"exchange-016"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4556#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":15696,"voices":67}},{"id":"h17-20051129-5","meetingId":"h17-cm11","date":"2005年11月29日","dateIso":"2005-11-29","committee":"総務委員会","time":"午前１０時０５分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の２、報告事項","agenda":"の２、報告事項","exchanges":[{"speaker":"鈴木（真）委員","kind":"意見","question":"電子申請ができることで、大分楽になることが多いと思うんですけれども、電子申請の登録の関係ですけれども、区のホームページで電子申請サービスをクリックすると裏の４ページにいきますね。全体の中の１４件ですけれども、先に行けばもっといろいろなところが出ると思うんですけれども、現状としては保健所関係というのはどのぐらいの数なのか、その２点。","respondent":"小野情報システム課長","answer":"したがって、今回のモデル実施をする中で、保健所関係の手続については、引き続き検討して広げていくということで、かなり利用者の方もいろいろ届け出の部分の負担が少なくなるのではないかと思います。","voiceIndex":9,"id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"こちらの情報を出すためではなくて、自分が手続をするためにという、そちらの感覚で何か検討できないかなというのが１点です。保健所が２５０あると聞いて、少し驚いたのですけれども、前に薬局の方にお会いしたときに、保健所の申請書は何で電子発信の中に載っていないのかと言われたことがあったんです。それは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-002"},{"speaker":"三村委員","kind":"質問","question":"今の鈴木真澄委員の質問に関連してですけれども、全く意見としては同じで、利用者にとって不利益がなければＩＤとかパスワードはなるべくつけない方向で考えていったほうがいいと思うんです。実際に粗大ごみの収集で、インターネット上で申込みをすると、住所や何かをその場で入力をして、それで終了という、そういうような形でもいいのではないかと思うんです。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"原委員","kind":"確認","question":"一つだけ確認をさせてください。全庁でやるのだけれども、東京電子自治体共同運営サービスはどういう団体で、どういう事業を今まで請け負っていて、どういう形で品川区が係わっている団体なのか。","respondent":"小野情報システム課長","answer":"東京電子自治体共同運営サービスは、今ご説明いたしました電子申請と電子調達を東京都内の区市町村が共同して運営していくという目的のためにつくられた協議会です。団体の性格といたしましては、自治体の協議会ということで、特に任意団体です。","voiceIndex":13,"id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると、この分担金というのがどのぐらいの費用がかかって、もう一つは事業の範囲ですが、今後もっとほかの利用価値というか、利用方法とかいろいろあると思うんですが、その辺のところがどういうふうになっているのか教えてください。","respondent":"小野情報システム課長","answer":"サービスですけれども、今回ご説明いたしました電子申請サービス、それから入札関係の調達サービス、それからまだ品川区は行っておりませんけれども、実際に利用料だとか手数料が関係しますけれども電子決済のサービス。","voiceIndex":15,"id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"そうすると、将来的には使い方が広がってきて、今お話しされたような職員も使えるし一般の方々も使えるということなので、利用の程度というのはもっといろいろ考えられるわけでしょうか。","respondent":"小野情報システム課長","answer":"料金の決済等も含めて出てきますと、かなり手続が可能になりますので、今１４手続で出発しますけれども、かなりの幅の手続が将来的には可能になると考えております。","voiceIndex":17,"id":"exchange-006"},{"speaker":"宮崎委員","kind":"意見","question":"今、品川区の負担で１年間１,０００万円、５年間で５,０００万円というお話だったんですけれども、今回モデル実施ということですので、どういう成果があったら進めていくのかとか、これはやめるとか、そういうことも含めたモデル実施なのか、いわゆる費用対効果をどのように考えているのかと思うんです。例えば利用が少ないのにやっていくのかということです。","respondent":"小野情報システム課長","answer":"電子申請ですので、証明書自体も電子的に出せる証明書が社会的に認知されるところまで進んでこないと、本来の電子申請の意味が出てこないだろうと思うんですが、将来的にはこういう方向に進んでいくと考えておりますので、今回のモデル実施は。","voiceIndex":19,"id":"exchange-007"},{"speaker":"宮崎委員","kind":"確認","question":"方向としては電子申請とか、そういう方向に行くだろうと思うんですけれども、ほかのところでもなかなか進んでいないというのは聞きます。住基カードもそうでしたけれども、無理に進めるみたいないことがあってはいけないと思うんです。一つ確認しておきたいんですけれども、今までの手続は当然変更してやるだろうと思うんですけれども、そこのところはどのように考えているのか。","respondent":"小野情報システム課長","answer":"電子申請は新しい手続の方法を一つ増やしたということでございまして、従来から行っているものについては従来どおりです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"宮崎委員","kind":"質問・要望","question":"単純な質問ですが、例えば窓口に行きますと、いろいろ申請書の記載に不備があると、そこで「ここは違います」と言われることがあるんですけれども、例えば電子申請の場合、全く単純な間違いも含めて、そのまま入ってしまうのか、つじつまが合わないとはねられるとか、そういう仕組みになっているんですか。","respondent":"小野情報システム課長","answer":"申請サンプルを利用されている利用者が、今の手続がどの審査の段階にあるかという、進行状況を見ることができるようになっております。","voiceIndex":23,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"質問","question":"今の件ですけれども、例えば記載の方法でよくわからないことがあると、先ほどコールセンターというお話があったんですけれども、そうするとコールセンターは実務的なところで、申請書の書き方も含めてかなり専門的な知識を持った方が対応するということでしょうか。","respondent":"小野情報システム課長","answer":"そのとおりです。","voiceIndex":25,"id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"確認","question":"１点確認ですけれども、今の中で東京電子自治体共同運営サービスに対して、品川区は１,０００万円の負担というのが出ていたんですけれども、この１,０００万円というのは前回の委員会で出た電子入札に係わったときには１,０００万円ですよね。新たにここで１,０００万円を払うというニュアンスに聞こえているんですけれども、その辺だけ確認しておきたいと思います。","respondent":"小野情報システム課長","answer":"全部のサービスを含めて電子申請、電子調達、決済、コールセンター、ヘルプデスク、これらのものを全部含めて年間１,０００万円のインターネットに係る経費です。","voiceIndex":27,"id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今までの質疑が、新たに１,０００万円が載っているような答弁だったような気がしたので、確認しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤田委員","kind":"質問","question":"この１年間で保健所等の手続の(1) から(14)までの件数はどれぐらいあったのか、わからなければわからないでいいですけれども、わかれば教えてください。","respondent":"小野情報システム課長","answer":"申し訳ございません。今、手元に資料がございません。","voiceIndex":30,"id":"exchange-013"},{"speaker":"高星委員","kind":"質問・要望","question":"インターネットが絡んでくると、どうも自分が苦手なものですから、なかなか前向きに入っていけないのだけれども、いろいろな犯罪の温床みたいな形になって、先ほど課長がおっしゃったように、電子区役所の関係は一向に伸びが悪いという中で、よく区内のいろいろな動きを見ても、例えば電子申請によってよかったという声があまり聞こえないので、正直私はよかったと思うのは。","respondent":"小野情報システム課長","answer":"やはり、今回のモデル実施の中で、委員ご指摘のように、本当に区民に使われる電子申請はどういうものなのか、それからどういう仕事の流れの中でやっていけば、より区民にも使いやすく、そして事務の処理が合理的にできるのか、こういうものを十分検証いたしまして。","voiceIndex":35,"id":"exchange-014"},{"speaker":"高星委員","kind":"質問","question":"笑い事なんだけれども、笑い事ではない大事なことだと思うし、ささいなことだけれども大事なことだと思うので、きちんとわかりやすくだれもが率直に思っている疑問をきちんと説明しながら、コマーシャルする必要があるだろうと思うので、よろしくお願いしたいと思います。あまりにも数値が上がらないと、何のために課長の席を設けたのかわからなくなってしまうので、お願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"中島副委員長","kind":"質問","question":"今の話と関連するんですが、結構地方に行くと電子申請をすると画面に大抵女性ですけれども、画面に人が映って、質問に対していろいろアドバイスをしてくれるシステムがありますね。こういったことは今後は取り入れていく予定はあるのでしょうか。","respondent":"小野情報システム課長","answer":"東京電子自治体共同運営サービスの中では、今のところこういうサービスをシステムに盛り込むという予定はございません。","voiceIndex":38,"id":"exchange-016"},{"speaker":"中島副委員長","kind":"質問・要望","question":"ですけれども、やはり高齢になってくると、なかなか思っているように言うことを聞いてくれないという実態もあると思いますので、やはり区民の方に親切な対応ということでは、そういうことも早いうちから検討しておけば、余分な予算をかけなくても効率的にいくと思いますので、これは要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問・要望","question":"公園の計画ですね、どのようにつくろうかというのを聞きたいんですけれども、以前しながわ中央公園の計画の際に、住民からのアンケートでスケボーの要望がかなりあって、そういう要望にこたえてほしいと、ほかの会派も言ったことがあったと思うんですけれども、そういう要望が考慮されてもいいのではないかと思っているんですけれども、次の報告事項でもフットサルの貸し出しをやるとなっていますけれども。","respondent":"日下部企画財政課長","answer":"公園計画についてのお尋ねですけれども、東品川海上公園につきましては、もともとかなり以前から長期計画の中に位置づけております「水とみどりのネットワーク」ということで、昨日ご視察いただいてもおわかりのように、海に面しているということもありまして。","voiceIndex":45,"id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区の考えはあるかと思うんですけれども、やはり住民の要望が全く考慮されていないような気がしてしようがないんです。やはり、それだけの要望が強いというのは、計画をつくる時の住民要望の把握の仕方というか、そういうところが不十分というか残念だなと言っておきたいと思います。今後のときは、ぜひそういうところを考慮していただきたいということを要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":47,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"昨日見せていただいて、すごくきれいな公園で私も時々近いから寄るんですけれども、噴水ができたら、またいいものになるのを期待します。今後の関係ですけれども、昨日いただいたカラー刷りの中で、斜線になっていてまだ区が交換できていない部分ですけれども、この辺の今後の予定はどうなっているのか、お答えできる範囲で結構ですけれども、お願いできればと思います。","respondent":"日下部企画財政課長、鷹倉経理課長","answer":"一方では、今お話に出ました旧東海道とルネッサンスをいろいろうまくつなげていこうではないかという構想が進んでおりますので、そういった意味におきましては、東品川海上公園につきましても。ここを交換する際に、私どもが持っているパイプラインに入っているということもあって、いろいろ補償がうまくいっていないという話を聞いてあります。","voiceIndex":48,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"これは部署が違ってしまうかもしれないけれども、全体の考え方としてお願いしたい。先ほど水辺のルネッサンスという中で、公園が完成した暁にはというお話だったけれども、もう既にあれだけいい公園になっている中で、もっとアピールしていくべきではないか、もったいないと思うんです。せっかくなら、もっと人に来てもらえるようにやってもらいたいということで、その辺のお答えがいただければ。","respondent":"中川原広報広聴課長","answer":"ちょうど１２月１日号のカラーのトップで紹介いたしましたので、あのページがとても好評なので、効果があってきれいだから訪れてくださればと思います。","voiceIndex":51,"id":"exchange-021"},{"speaker":"三村委員","kind":"質問・要望","question":"昨日視察したときに、だれでもトイレが新しく設置されるということだったのですけれども、ほかの公園を見てきたときに、だれでもトイレの夜間の利用で不適切な利用があるということで鍵がついていたりします。実際に利用したいときに利用できないという話も聞いていまして、その辺はどのように対応されるのか、わかれば教えていただきたいと思います。","respondent":"鷹倉経理課長","answer":"トイレの使用までは把握していないのですが、この辺のところは必要かなと思いまして、所管の方に伝えたいと思います。","voiceIndex":53,"id":"exchange-022"},{"speaker":"三村委員","kind":"意見","question":"もう１点、これだけ広い公園で、よくドッグランを欲しいという話もよく聞くのですけれども、集客という面でも、私は結構近いのでよく利用するのですけれども、引き綱を使わずに犬を放されている方が実際にいます。","respondent":"日下部企画財政課長","answer":"そういう兼ね合いもありまして、現実問題、この中に設けることはしておりません。ただ、先ほど申し上げましたように、品川区民の方にとっては一番近くの公園にドッグランがありますので、当面はそちらのほうをご活用いただくということでお考えいただければと考えております。","voiceIndex":55,"id":"exchange-023"},{"speaker":"藤田委員","kind":"質問・要望","question":"それと、時計ですが、今回の設計概要の中に一つもないですね。太陽光を利用したデザインのいい時計を、ぜひまちづくり事業部に伝えていただきたいのですけれども、これが入っていない。もう一つは、「水とみどりのネットワーク」と言いますけれども、よく２３区の自治体でも苦慮して、子どもたちが水の中に入って魚を取ったりいろいろ楽しんでいるちょっとしたスペースなのですけれども、それをやっている。","respondent":"日下部企画財政課長","answer":"今、委員おっしゃったような趣旨は、この中に盛り込まれているということで、ご理解いただきたいと思います。それから、香りを楽しむ樹木、時計の関係につきましては、この表示だけではわからない部分がありますので、所管にしっかりと伝えてまいりたいと考えております。","voiceIndex":57,"id":"exchange-024"},{"speaker":"原委員","kind":"質問","question":"ここで聞いていいのかどうか、かなりの広さのものなので、管理体制というのはどういう形を考えていらっしゃるのでしょうか。昨日も一生懸命雑草を摘んでいましたけれども、どういう形を考えてられているのかと思うんだけれども、わかったら教えてください。","respondent":"日下部企画財政課長","answer":"今、ご指摘のように、大変広い空間です。管理につきましては、昨日もジャンパーを着た方が一生懸命やられておりましたけれども、こちらについては確か民間の事業者に委託をして、かなりきちんとした形で管理をしていくという体制になってあります。","voiceIndex":59,"id":"exchange-025"},{"speaker":"本田委員","kind":"質問","question":"高木が少ないですし、何かちまちました緑だけが少しあるというような形ではなくて、これだけ広い公園ですから、やがて１０年、２０年、３０年経った後、本当に緑のあるいい公園だと、近所には福栄会もありますし、高齢化も進んでいって、訪ねて遊べる憩いの持てる公園となっていくだろうと思うんですけれども、その辺が十分配慮されているのか、植栽だけを見て感じるんですけれども、所管外かもしれませんが。","respondent":"日下部企画財政課長","answer":"実は昨日、担当から説明がありましたけれども、この絵で見ますと実感がなかなかわいてこないのですが、平成１８年度に予定しております下水道ポンプ場の脇の空間が、そんなではないですけれども、このところに重点的に木を植えていくという説明が昨日なされておりました。","voiceIndex":61,"id":"exchange-026"},{"speaker":"本田委員","kind":"質問・要望","question":"今になってみると、２０年経って桜の木も大きくなって、随分人が花見で集まる場所になっています。大きな駐車場があるということもあるんですけれども、そういう点で、臨海部における品川区の重要な緑のスポットという東品川海上公園の持つ位置というものを今後とも重視されて、その辺の植栽については十分考えていただきたいなと感じておりますので、よろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-027"},{"speaker":"中島副委員長","kind":"質問・要望","question":"直接ではないのですが、昨日あそこを見ましたときに、今のお話しを聞いていて水と緑のネットワークということで、非常にこれから有名になる公園かなと思っているのですが、赤い水門がありますね。あれが目立ってしまって、せっかくきれいなのに水門が景色を非常に壊してしまうなと気がしたのですが、あの辺は東京都だと思うんですが、東京都に要望するということは可能なのでしょうか。","respondent":"日下部企画財政課長","answer":"実は私は昨日行きまして、副委員長と同じような感想を持ちましたけれども、まちづくり事業部にそういうご意見があったということで、改善できるのかどうか、その辺は伝えておきたいと思います。","voiceIndex":64,"id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"スタジオがすぐ近くにあるので、逆に待っているのではなくて売り込んでいくべきではないかと思いました。福栄会側のところに自転車を置くと、会社があって邪魔だというのでどかされたりした記憶があるので、天王洲の野球場まで行かないとないかなと思うんですけれども、少し印象が薄かったので、気になったので、要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":70,"id":"exchange-029"},{"speaker":"三村委員","kind":"質問・要望","question":"今回、月額３００万円で貸し出しをするということですけれども、ほかにも申し出があったのかということと、ほかと比較してもう少し高い金額で貸せるようなところがあったのか。それから、３００万円の根拠があれば教えていただきたい。","respondent":"鷹倉経理課長","answer":"実はここは来年１月までに再開発の関係で取り壊されるという事情もあり、近辺の場所を探されていた。ちょうど私ども学校を検討していた中で、どうだという話が来た経緯があります。その中で学校のほうが難しいというのがあって、この際検討させていただいたというようなことです。","voiceIndex":76,"id":"exchange-030"},{"speaker":"鈴木（真）委員","kind":"質問","question":"すべて特殊事情に合わせて指定してしまうのか、考え方としてどちらでしょうか。","respondent":"榎本行財政改革担当課長","answer":"この経緯の部分、ほかとの交渉は私のほうがあたっているので、説明します。ここはあくまでも限定された北品川の開発が始まるまでの間ということで、期間限定の暫定利用ということで、そういう形にはしておりません。","voiceIndex":78,"id":"exchange-031"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"確かに暫定期間ということでわかるんですけれども、民間で考えたときに、例えば暫定期間であっても、いいですよと応募することがあると思うんです。大変失礼かもわかりませんけれども、現実論として開発がいつ進んでいくか、できるかあると思うんです。もう一つは、総合体育館ができますけれども、施設としてある程度区がやっていくとすると、どのぐらいの負担が出ていたのか、その辺を教えていただきたい。","respondent":"榎本行財政改革担当課長","answer":"ほかにも事業者があるというのはいいんですけれども、やはり今でもあそこの地区限定の条件付けを納得してもらうというのは、なかなか全体の経過の中では難しいのかなという形で、かなりこの会社につきましても初期投資の部分が必要だということで。","voiceIndex":80,"id":"exchange-032"},{"speaker":"鈴木（真）委員","kind":"意見","question":"費用がかかるから、月額３００万円というと大きいと思うんですけれども、例えば取り壊すということを検討しなかったのかということと、このまま行ったときにこれで５面つくるというと、体育館のワンフロア部分だけで５年使うのか。もしワンフロアだけ使うのだったら、２階部分とかもっと活用できる部分がないのかとい点、その辺をまずお願いします。","respondent":"榎本行財政改革担当課長","answer":"取り壊しの部分につきましては、再開発の権利変換の中で更地の部分と建物付きの部分ですと、やはり権利変換価格に差が出るということで、建物は残すという考え方でおります。建物は残り、一応そこに維持管理がなく、いかに有効活用するかという中で、こういう形を取りました。","voiceIndex":82,"id":"exchange-033"},{"speaker":"鈴木（真）委員","kind":"意見","question":"確かに、フットサルでいい活用だと思うんですけれども、この場所でやっていく営業時間というのは、大体フットサルをやる人は結構遅い時間までやっているのを考えると、近隣にはマンションだとか家もあるので、早く終わればいいのだけれども、特に屋上は何時頃までやるかによって、周りに影響が出ないかどうか、その辺が心配なので、その辺の対応を考えていただければと思うんですが。","respondent":"榎本行財政改革担当課長","answer":"営業時間としては朝９時から２４時まで考えているということで、ただし屋上のコートにつきましては、夜１０時までということで時間の制限をしているということです。","voiceIndex":84,"id":"exchange-034"},{"speaker":"鈴木（真）委員","kind":"意見","question":"２４時というと、やはり室内で、あそこは夏場は冷房があまりきいていないんですけれども、現実論として冷房を直していないと思うし、何年か前に外国の中学生が来て日射病になったという記憶もあります。開けられてしまうと、結構音の影響が外に出るのではないかと気になりました。五反田は１１時半と言っていても、あそこはあまり住まいがない部分だと思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":86,"id":"exchange-035"},{"speaker":"高星委員","kind":"確認","question":"先ほども出た話ですけれども、貸付相手のアビロージャパン(株)がどういう会社かわからないのですけれども、なぜそこが相手なのかということを聞きたいと思っているんです。僕はその辺のところはよくわからないからお聞きしたいのですけれども、そういったことをきちんと議論された上で、アビロージャパンという形になっていたのかどうか、その辺のところだけ確認する意味でお聞きしたいなと思います。","respondent":"榎本行財政改革担当課長","answer":"フットサルにつきましては、実は生涯学習課にもかなりフットサルの要望が出ておりまして、その部分をどのように対応するかということでつくったという経緯がありましたので、フットサルの部分は区が直接ではなく民間事業者を使っての形で。","voiceIndex":87,"id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"今回、１年間の契約で、もちろん更新は可能となっているんですが、北品川区五丁目第１地区市街地再開発の進捗状況といいますか、その辺はどんなところまで進んでいるのでしょうか、計画より大分遅れておりますね。そうすると、どのぐらいの期間なのかな、そこのところをどのようにみているのかお聞かせいただければと思います。","respondent":"榎本行財政改革担当課長","answer":"詳しいところはわかりませんけれども、私どもが聞いている範囲ですと、来年にはある程度目処が立って、着工時期もここ二、三年以内にはつくという形で聞いておりますで、その間の暫定利用という形での利用方法を考えて、こういう形で貸付をすることにしたということです。","voiceIndex":89,"id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問・要望","question":"それをアビロージャパン(株)が当然それも持ちながら月額３００万円、年間３,６００万円を負担して、それで事業をやるということだと思うんですけれども、そもそもこれだけ人気があるというか、要望があるのであれば、そもそもこういう要望を区がしっかり受けとめる必要があると思うんです。最初から民間への貸し出しということではなくて、こういう要望を区がしっかり受けとめることが必要だと思うんです。","respondent":"榎本行財政改革担当課長","answer":"利用料と区の施設との比較については、フットサルコート自体を区がやったらどうなのかという点もありますけれども、実際上、フットサルというもの自体が長期的な需要がどういう形になるのかということもありまして、実際上、フットサルコートが今後１０年。","voiceIndex":91,"id":"exchange-038"},{"speaker":"宮崎委員","kind":"質問","question":"それと、アビロージャパン(株)は、１面１時間あたり１万５,０００円とおっしゃっていましたけれども、私の知り合いの方は大体１回借りると大体２時間とか２時間半とかやるようです。例えば、品川区に在住・在勤者に対しては割り引きするという説明ですけれども、区がそのままやっていた場合、今度は貸し出しての場合と、利用者の側から見たらどのぐらいの料金の差が出てくるのでしょうか。","respondent":"榎本行財政改革担当課長","answer":"そういう形での比較はしておりませんけれども、実際に今現在の利用の需要がその金額でもあるという形で民間事業者が参入してきているという形ですので、そういった形での有効活用を図っていきたいという考えです。","voiceIndex":93,"id":"exchange-039"},{"speaker":"宮崎委員","kind":"意見","question":"やはり、そういうところをしっかり計算しなければ、一体３００万円というのはどういう根拠なのかということになってくるのです。どうやって３００万円になってきたのか、その根拠が全くわからないですね。区のほうでやったら、確かに１億５,０００万円かかるというお話ですけれども、そういうその場の勘定だけで言っていいのかなというのが非常に疑問です。そこのところで何か説明はありますか。","respondent":"新美企画部長","answer":"したがいまして、これは従来から申し上げているかと思いますが、今の古い総合体育館は普通財産にし、北品川五丁目第１地区市街地再開発の用地として活用していくという方針が固まっている。これがまず前提としています。","voiceIndex":95,"id":"exchange-040"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう経過があったと思うんです。やはり、そこには区民の要望から出発する考え方が欠落しているのではないかと、この感想で述べておきたいと思います。例えば今の学校だとか、そういうところが使うのはわかりますけれども、私は住民の要望があるのに企業にすっといくというのは、やはりどう考えてもおかしいということを申し述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1704#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":29476,"voices":111}},{"id":"h17-20051130-11","meetingId":"h17-cm11","date":"2005年11月30日","dateIso":"2005-11-30","committee":"自治制度特別委員会","time":"午前１０時１０分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"本日の進め方でございますが、まず初めに、(3) の基礎的自治体（特別区としての品川区）のあり方","agenda":"本日の進め方でございますが、まず初めに、(3) の基礎的自治体（特別区としての品川区）のあり方","exchanges":[{"speaker":"石田委員","kind":"質問","question":"読ませていただいて、この前ご説明もいただきましたが、わからないのは、これが出ることによって、中身的には道州制や区の再編みたいなことも含めて、さまざまな方向性をいろいろな形で検討しなければならないということが書いてあるわけですけれども、これを特別区協議会で出されたということで、その取り扱いが今後どのようになっていくのか、あとは国の２６次までに進んでいるのか。","respondent":"日下部企画財政課長","answer":"だた、先ほど申し上げましたように、今回の報告書はあくまでも特別区の今後のあり方についての論議の素材としての活用ということでありますので、実際、地方制度調査会の検討の俎上に上るということは、これがかなり制度的にももう少ししっかりとした下地ができて。","voiceIndex":3,"id":"exchange-001"},{"speaker":"石田委員","kind":"質問・要望","question":"もう一段教えていただきたいんですが、今、国の関係はまだまだ時間がかかるということで、結構ですが、論議の俎上に上がるということは、「俎上」というのはどこの俎上に上がるんでしょうか。は別の機関をつくって、そこでもう一回議論をしていくのかとか、その「俎上に上がる」というのは、どこに上がると今、考えればよろしいんですか。","respondent":"日下部企画財政課長","answer":"今回のこの検討そのものにつきましては、平成１５年に区長会から制度改革後の特別区のあり方ということで、それに特別区１２年で都区制度改革は実現したけれども、まだまだいろいろな将来方向についての課題が山積をしている。","voiceIndex":5,"id":"exchange-002"},{"speaker":"石田委員","kind":"質問・要望","question":"主要５課題とかはもう置いておきますけれども、都区のあり方を考えていく上において、特別区の方からそれなりに強い意思を出していくということであるならば、これに基づいた議論をどれぐらい先を見越して、例えばこれを３年後にある程度特別区としてもやるんだとか、５年後ぐらいにはある程度の方向性は示すよという、先をある程度決めて議論をしていこうとされているのか、とりあえず多分。","respondent":"日下部企画財政課長","answer":"今後の取り扱いということになろうかと思いますけれども、今、私が承知している限りでは、期限をどのくらいに設定してという形での取りまとめといいますか、考え方は出されてございません。","voiceIndex":7,"id":"exchange-003"},{"speaker":"本田委員","kind":"質問","question":"つまり、２つはみんな似たようなものですけれども、３つのシナリオはかなり違った形態ですから。各区の区長の姿勢が違うというのは２３区が大事なところで足並みがそろわないということを東京都に見透かされてしまうし、当面の問題解決にも逆に２３区は結局そろっていないということにもなりかねないと思うんですけれども、その辺の議論はどう進んでいるでしょうか。","respondent":"日下部企画財政課長","answer":"そういうことで、ここに来まして、制度論議というのがかなりいろいろな形で高まってきておりますので、そういうことともあわせまして、今回の報告書というのは、いろいろな形でこれがたたき台になって、将来方向の検討に有効に生かしていけるのではないかと考えているところです。","voiceIndex":9,"id":"exchange-004"},{"speaker":"本田委員","kind":"質問","question":"今朝の新聞に、朝日だったか、東京新聞だったか、珍しく都区制度の問題が報じられました。短い記事だったんですけれども、この調査会の報告が載っていたんです。この当初の報告を参考にしますという程度ではなくて、もっとインパクトのある事件拡充に結びついたものの見方で、見解を出しておくべきではないかなと、きょうの新聞報道を見まして、感じているところなんですが、そういう動きはないんですか。","respondent":"日下部企画財政課長","answer":"私どもとしましては、こういう取り組みをしているわけですけれども、今後とも先ほど申し上げましたように、いろいろな形での動きは出てまいりますので、その辺にあわせまして、タイミングを見計らいまして。","voiceIndex":11,"id":"exchange-005"},{"speaker":"塚本委員","kind":"意見","question":"特別区協議会、特別区制度調査会、これは２３区側が自分たちの考えをまとめたということですね。東京都側は全く違ったと。","respondent":"日下部企画財政課長","answer":"このタイトルにあらわれておりますように、東京都としては、１つは自治制度のあり方、もう一つは行財政改革について、財政再建の問題も大きな課題になっておりますので、その辺と抱き合わせで、この内容の検討を進めているという中で、昨日。","voiceIndex":14,"id":"exchange-006"},{"speaker":"塚本委員","kind":"意見","question":"これが東京都側がこういう２３区側と対抗できるよう、財政改革が入っていても結構ですけれども、肝心の部分がそれに対抗できるような話がしっかり出てくるのか、対抗できるようなものが時間的にどういうふうにできていくかなということが見えてこないと、本当の論戦といいますか、お互いに真剣に自分たちの考えをまとめてテーブルの上につくという状況ができてこないと、私は理解するんだけれども。","respondent":"日下部企画財政課長","answer":"ただ、その間にまた今回のような形で中間的な報告がなされるかどうかというところまでは、まだ私どもは承知しておりませんけれども、最終形は来年度中です。ですからいずれにしましても、今後の東京都の検討の状況については十分、私どもも注目をしてまいりたいと考えております。","voiceIndex":16,"id":"exchange-007"},{"speaker":"塚本委員","kind":"質問・要望","question":"それから道州制ということになると、都区間でやった前提を突き崩すような大きな話ですから、我々は道州制というと、適当に県がなくなって、広域的な県の連合体みたいなものができるのかというイメージを持って、詳しくはわからないですね。今まで、もう１０年ぐらい前ですか、道州制というのはこんなものだよという、そんな話が出てきたのは。","respondent":"日下部企画財政課長","answer":"間の都道府県については都道府県を越えた圏域でのしっかりした役割を担えるような形で再編をすべきだという基本的な考え方がベースになって、今、道州制の論議が進められてまいりまして、今年の２８次の調査会の５月か６月ぐらいには。","voiceIndex":18,"id":"exchange-008"},{"speaker":"塚本委員","kind":"質問・要望","question":"大分わかりやすいお話でした。市町村合併がどんどん進んで、基礎的自治体の数を減らしていく。当然の方向だと。当然のことです。ということは、道州制というのは別の言い方をドラスティックに言えば、都府県合併ということを求めているんだと理解していいのかと。道州制を本当に導入しようとしたら、どういう手順で、基礎的な考え方はどうなのかということをもう一度お願いします。","respondent":"日下部企画財政課長","answer":"今のご質問の件ですけれども、結論から申し上げますと、最終報告は２月ですが、今現在、調査会の中でまとめられております中身でいきますと、あくまで都道府県の合併です。間に中間的なものはつくらない。","voiceIndex":20,"id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"東京都を見ると、人口規模では十分に大き過ぎるぐらい大きいですから、ほかのところがそうやってきて、埼玉県や神奈川県の周辺はどうなるんだと。そういうところを中心にして、必然的に道州制といいますか、都府県だって、府県だって必要だよという話なのか。東京都の位置づけというのは、その中でちょっと間尺が足りにくいところがあると思うんですけれども、その辺の議論はされているんですか。","respondent":"日下部企画財政課長","answer":"今、出されております考え方は２通りございまして、１つは２３区、東京都全体あるいは２３区を絞りまして、そこだけを首都機能を持った大都市州という形で、面積的には狭いんですけれども、そこを独立させるというのが１つの案です。","voiceIndex":22,"id":"exchange-010"},{"speaker":"土井委員","kind":"質問","question":"これはそのとおりだと思うんです。品川区の場合は真ん中ですから、どっちに転がってもいいやという話になるのかもしれないけれども、それでは全体としての今までのいろいろな意味での仲間意識も薄れますから、やるとすれば、その２３区でやるかどうか別として、それぞれの市が財政調整をやるんだ、やれるんだという組織的な、あるいは制度的なものをみずからつくっていく。","respondent":"日下部企画財政課長","answer":"それによって、こういう３つのシナリオが描かれてきているんだということで、私どもも認識をしています。","voiceIndex":24,"id":"exchange-011"},{"speaker":"塚本委員","kind":"質問・要望","question":"それの中にやり方が２つある。そこのところの訴えに、要するに意思疎通、２３区の区長がこのことを勉強して、おれたちにもできるんだというような準備段階をする時期に来ていると思うんですけれども、そういう報告、そういうことをやっているという話も聞こえてこないんだけれども、どうなっているか教えていただきたい。","respondent":"日下部企画財政課長","answer":"その研究会の中で、最大の検討の素材として取り扱いがされていくと思いますし、その中でいろいろ議論が成熟してくれば、それをもとにして、また２３区の区長にお諮りをして、次のステップに進んでいくという形におそらくなってくると思います。","voiceIndex":26,"id":"exchange-012"},{"speaker":"塚本委員","kind":"質問・要望","question":"ぜひそういうことがなければ、本当の力がわいてこないと思うんです。これはざっくばらんに言い過ぎですけれども、そういうようなためらいが心理的にあるかもしれないので、そこのところはやはりいろいろなやり方があるので、研究をしっかりするということで、解けてくる部分があるのではないかと思いますので、ぜひそういう基礎的な研究・勉強を積み重ねていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-013"},{"speaker":"石田委員","kind":"質問・要望","question":"いろいろ道州制とかのお話も、地方制度調査会の話も出てきたので、１点だけお伺いしたいんですが、先ほど中心区というのか、中心地、ワシントンＤＣみたいな話があって、そう考えていくと、これは都の立場で考えると、例えばそこの部分を特別区の中で切り離して、残りの特別区のことを考えたら、先ほど言った大きな権限も与えられるから、政令指定都市みたいな形をつくっていこうとするならば、今で言う。","respondent":"日下部企画財政課長","answer":"ただいずれにしましても、ご指摘の情報をしっかりとって、適切な対応ができるようにということは、そのとおりでありますし、私どももそういった意味では今回の報告もそうなんですけれども、２３区側の目だけでと。","voiceIndex":29,"id":"exchange-014"},{"speaker":"菊地副委員長","kind":"質問・要望","question":"それともう一つ、これはこの制度の説明とはちょっと違いますけれども、前回の課長の説明のときに現実の問題で、法人税の住民税の見直しがあって、これから影響が出てくるという話がありましたけれども、その辺が区にどういうふうに影響が出てくるのか、そこもちょっと教えていただきたい。","respondent":"日下部企画財政課長","answer":"既に法人事業税について見直しがされまして、東京都はたしか６００億円ほどの減収になるということで、東京都が非常に強い反対の姿勢を国にもさんざん伝えているところですが、次の課題として今、法人住民税の見直し問題が検討の対象に挙がっているということで承知をしています。","voiceIndex":31,"id":"exchange-015"}]},{"id":"topic-02","title":"特定事件調査(2) 清掃制度に関すること","agenda":"特定事件調査(2) 清掃制度に関すること","exchanges":[{"speaker":"若林委員","kind":"確認","question":"確認書の方なんですが、理解できないところがありますので、矛盾という言い方が正しいかどうかわかりませんが、ちょっと違うニュアンスなので、１番目には雇上会社がこれまで清掃事業に果たしてきた役割云々と、十分に理解して、尊重していくことを基本とするとありますが、２番に行きますと、これを踏まえた上で、ただしそのうちの一部の資源。","respondent":"中山清掃リサイクル課長","answer":"したがって、歴史的経過は経過として、今度は契約の方法論として各区契約ができるというのが２番のところになっているです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、今までは清掃協議会とこの雇上協会ですか、東京環境保全協会等で一括して進めてやっておりまして、今回、それ以外のこの２項目目にあります資源および粗大ごみについては、そこを切り離して、さっきありました新規の業者にまた門戸を開くという、具体的にはそういう理解でよろしいでしょうか。","respondent":"中山清掃リサイクル課長","answer":"ちょっと説明をすると、十分ご理解いただけなかった説明であったかと思いますので、３番にそこで新たに各区契約する場合、この２の場合、資源、粗大ごみの収集運搬に関する契約を各区契約する場合は当分の間と書いておりますけれども。","voiceIndex":39,"id":"exchange-017"},{"speaker":"若林委員","kind":"確認","question":"なので、この確認書によって、それを与えてまたという形を教えていただけますでしょうか。","respondent":"中山清掃リサイクル課長","answer":"実際の交渉の場面に立ち会っていない部分があって、どこまでそういうところのやりとりがあったかというのは、この文書以外には読めないので、先ほどご説明した覚書の別紙のところをおめくりいただきますと、歴史的経過の中に基本的考え方というのが冒頭ありまして。","voiceIndex":41,"id":"exchange-018"},{"speaker":"若林委員","kind":"意見","question":"よくわかりました。各区の対応になって、その代表である特別区長会の会長が２３区のものも含めて、雇上会社等々がこれまで東京環境保全協会との契約だったものが今回、各区でできるように一致したということで、その部分は引き続きお互いにまだ認識しましょうと。ただ、時代の流れに乗って、資源ごみ、粗大ごみの部分のところは、またこっち側で考えてきましたよというようなところで、理解をいたしました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":43,"id":"exchange-019"},{"speaker":"石田委員","kind":"確認","question":"確認書の件でお伺いしたいのは、経緯もすごくわかりました。大変御苦労をされていると思いますが、抜本的な改革の中で、協議会のあり方については、さまざまある一定方向が出てきた中で、この確認書を出されたんですが、１つお聞きしたいのは、この確認書をしたことで、本当の確認だけをしたのか、先送りをしたのか、一歩前進をしたと思っていらっしゃるのか、その辺を教えてほしい。","respondent":"岩崎環境清掃事業部長","answer":"かなり抵抗があります。正直言ってすごいんです。ここでは申し上げられませんが、ぜひともこういう区の権限を十分に発揮できるような方向性で来年の４月を迎えたいと考えています。","voiceIndex":44,"id":"exchange-020"},{"speaker":"石田委員","kind":"質問・要望","question":"産業廃棄物を含め、これは持込手数料の件なんですが、私がわからないのかもしれないんですが、現実問題、一般廃棄物と産業廃棄物で、今、読みながらさまざま伺っていますが、中間処理業者が行っている部分、それから今はリサイクルセンターという名前でいろいろ中間的な処理をしている部分がいろいろ増えてきているわけですけれども、ここら辺のところから、各業界全体というのか、実際に出てくるごみ。","respondent":"岩崎環境清掃事業部長","answer":"事業系は有料ですけれども、家庭系は今のところ無料なので、無料の方に紛れて出しちゃうと、ずるできるわけです。これの対策を今後、より強めていかなければいけないと考えているところです。","voiceIndex":46,"id":"exchange-021"},{"speaker":"土井委員","kind":"質問・要望","question":"それからその意味で、この考え方は歴史的な要素もありながら、２番目のところでやってきた、これは歴史的な段階で資源ごみというのはなかったわけですね。その昔のことを言えば。この「当分の間」というものは、先ほどの持ち込みのあれですと、１５年ごとに直そうとかいう、何かありますけれども、利用者は何もないんですか。","respondent":"岩崎環境清掃事業部長","answer":"ただ、それに対して、どこまで向こうが折れてくるかという、向こうにもそういう意味での経営的な展望を持たせてやらないと、ただやっつければいいという問題ではありませんので、その辺のことがまだまだ５２社の雇上会社は不安感だけがあって。","voiceIndex":48,"id":"exchange-022"},{"speaker":"土井委員","kind":"確認","question":"お伺いしているのは、この確認書はもともと東京都の入った覚書等々だったからということでいらっしゃるのかもしれないけれども、現実問題、それは我々２３区と、一部事務組合、あるいは協議会というスタイルになっているはずのところに、いつまでも関係者ということで、環境局長だかがしゃしゃり出てくるのは、ちょっといかがなものかという意味なんです。","respondent":"中山清掃リサイクル課長","answer":"ですから、非常にこのもとの覚書の記載に伴うセレモニーとして出てきたということで、実質は今、委員がおっしゃったように区の中で、それは経過を踏まえるのも、新たに改革をするのも区の中での感覚ということで、今回。","voiceIndex":52,"id":"exchange-023"},{"speaker":"土井委員","kind":"意見","question":"前の方で、その辺でそうなっているから、とりあえず１回は出てこないといけないなという感じです。さっさと見直しちゃって、この次は区長と、何か環境保全協会とで当事者同士で決めますから、これをもってお引取りくださいと言わなくちゃいけなかったのではないかと思うんだけれども、それが言われていないのについては、ちょっと違和感を覚えます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":54,"id":"exchange-024"},{"speaker":"塚本委員","kind":"確認","question":"途中経過のお働き御苦労さまでしたというようなスタンスをとるべきじゃないか。説明を受ければわかるけど、この書類の字面を見て、何でまたこの人たちは親がかりのような顔をして出てくるのという印象を我々が受けるわけですから、どうぞ、改めて重ねて申し上げますけれども、そういうことでご努力願いますということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-025"},{"speaker":"井上委員","kind":"質問・要望","question":"原議長も出席されているので、ちょっと確認も含めてなんですが、議長会の報告のときに、廃棄物計画について区民に意見を聴取するということで、区の取り組みがどのようになっているかということが、自治制度もしくは区民委員会で報告があるのではないかというようなお話だったのですが、今日はここに廃棄物計画について報告がないんですが、今後、自治制度であるのか。","respondent":"中山清掃リサイクル課長","answer":"もちろん清掃一部事務組合の計画そのものの審議については前回、前々回で２３区としての、あるいは清掃一部事務組合の計画改定内容として当委員会で報告したです。","voiceIndex":56,"id":"exchange-026"},{"speaker":"井上委員","kind":"質問・要望","question":"ちょっと区民委員会の方に入ってしまうのかもしれませんが、そのことについて、ホームページ上でほかの区では意見を求めますというようなこともあったんですが、品川区は今、どうなっているのか、教えてください。","respondent":"中山清掃リサイクル課長","answer":"それから品川区の事業部ホームページの中でもリンクを張る形なんですけれども、一部事務組合の基本計画原案をごらんいただいて、パブリックコメントができるように、今、対応しております。","voiceIndex":58,"id":"exchange-027"}]},{"id":"topic-03","title":"特定事件調査、(1) 都区制度改革・主要５課題に関すること","agenda":"特定事件調査、(1) 都区制度改革・主要５課題に関すること","exchanges":[{"speaker":"石田委員","kind":"質問・要望","question":"１点だけ議長会、区長会の両方にお願いだけをしたいのは、もちろん今、すごく佳境に入ってきまして、区長会の会長としてぜひ頑張っていただきたいと思いますし、一丸となって統一区はやっているよというところを見せなければならないと思いますが、どうも伝わってくる話は、何とか地区とは言いませんが、何区とも言いませんが、そこら辺の幾つかの区の方なんかと話したりすると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-028"},{"speaker":"本田委員","kind":"提案","question":"議長の提案は結構ですし、ぜひよろしくお願いしたいと思うんですが、知事や議長に出すというのはいいんですけれども、聞くところによると、都議会各会派が必ずしも区側の我々の要望に同一歩調をとっているようでもないと、いわゆる会派によって、ニュアンスが何か違いがありそうですね。そういう点で、せっかくの要請行動ですから、都議会の各会派にも統一の要望書なり要請行動をぜひ加えていただきたいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":67,"id":"exchange-029"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回の委員会で、廃プラスチックのサーマルリサイクルについてもご報告いただいたんですが、ぜひ常にサーマルリサイクルを行っている大田区の第二工場に視察に行かせていただけたらと思っているんですが、時間の余裕のあるところで結構ですので、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5586#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":33984,"voices":74}},{"id":"h17-20051130-16","meetingId":"h17-cm11","date":"2005年11月30日","dateIso":"2005-11-30","committee":"街づくり特別委員会","time":"午前１０時０４分～午後２時１８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地の活用に関すること","agenda":"公有地の活用に関すること","exchanges":[{"speaker":"三上副委員長","kind":"質問・要望","question":"最終的にＴＯＣがこの金額の交渉等、いろいろなると思いますが、そういった点にあっては、当然、区民に公表できる時点であったならば、速やかにこれは公表すべきである、そしてまた、そういった校舎の建築費用を考えたときに、その費用負担については、一時金で支払いを当然求めていくものではないか、こういったふうに思っておりますので、そういった点を要望して、既に述べましたように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":3,"id":"exchange-001"},{"speaker":"本間委員","kind":"質問・要望","question":"「日野中学校跡地の利用計画案について：会派別意見一覧」の中に、私どもの会派の部分は３行でまとめてありますが、当初、この部分のテーマは、日野中学校跡地、これを公有財産としてどのように有効利用していくかというふうなことで来ましたものですから、その件につきましては、今までのやりとりの中で小学校の老朽化等々が出ておりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":4,"id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"大きな１点目ですけれども、関係住民からの意見や要望の尊重を何よりも第一義とすべきだということです。３点目は、この委員会でも若干議論になりましたけれども、いつ起きるかわからない首都直下型の震災に対する住民の高い関心、帰宅困難者の問題など、やっぱり防災強化が求められると。以下、その理由を３点記してありますが、まずは、地域住民の意見や要望、これの尊重が第一とされていない点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":5,"id":"exchange-003"},{"speaker":"伊藤副委員長","kind":"提案","question":"１番目は、これはすごく当たり前のことですけれども、品川区の公有地をさまざまな形で、新しい形で貸し出すわけですから、ＴＯＣとの調整を十分に行いまして、移転、改築費用、駐車場の賃貸料、それから期間、これら公有財産が最大限有効活用されるように努力を傾注することとなっていますけれども、その語句の中には、例えば、契約の仕方とか、それから。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問・要望","question":"６項目要望をいたします。それと、２番目なんですが、こちらも開校した後の土曜日、日曜日の地域開放の充実を図ること、３番目といたしましては、日野中学校跡地の工事が着工するまでの間、今、地域に開放していますグラウンドと第２グラウンドの開放を、着工するまでの間、２年間ですか、従来どおり充実をしていただきたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":7,"id":"exchange-005"},{"speaker":"西本委員","kind":"提案","question":"地域の調査も私たちは独自で行っておりますが、関係者、特に第一日野小学校のＰＴＡの方たちは、長年その環境を改善していただきたいという要望がかなりあったということを踏まえますと、今回の日野中学校への移転改築というのは非常に理解されるものだとしております。これについても、地域の方たちは非常に受け入れられているのではないかなと判断をしております。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"終わりに、この公有地の活用については、区民のために使うことが大前提で、ＴＯＣ内の会社、商店、それから、やはり地域住民にとって不利益にならないような方法をとるべきであると思いますし、ここは区の公有地活用について、区の姿勢が大変問われることだと思いますので、本事業に関連する工事内容や環境の変化について、近隣住民への詳しい説明とともに、ご意見ご要望をよくお聞きして。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"ネット・無所属の意見の中に、一斉に解体・建築をすれば、３年間で済むという話があるんです。ちょっとそこら辺が、今まで一気にというところが視野に入っていなかったので、その辺を少し確認をさせていただきたいと思うんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-008"},{"speaker":"須貝委員","kind":"質問","question":"その音をご近隣の方が１０年１２年にわたって、そのまま区も容認して貸し出すということは、地域の住民にとっては非常な苦痛を強いられる状況になると思いますので、そこはまだ交渉はこれからということなんですから、できるだけ短くできるような交渉をＴＯＣにして、地域にとってもいいような方向で第一日野小学校が使われるならば、それはやむを得ないんじゃないかなと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-009"},{"speaker":"西本委員","kind":"質問","question":"そうすると、ネット・無所属の考えというのは、ＴＯＣに貸してもいいということになるんですか。結局は、早く終わるということを考慮に入れているのであれば、ＴＯＣに貸し付けをしてもいいという内容でよろしいんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"どういう工事内容かというのも、現時点で正式に出ていないわけです。だから、こうなってこうなるんだということならば、もっと私もきちんとした話をできると思いますけれども、漠然としてただ１０年間、じゃあ、何が１０年間、はっきり言って、何が１２年間、だって、工事がいつから始まって、どういう工事をやって、例えば３期に分けてやるのか、２期に分けてやるのか、それも全然伺っておりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-011"},{"speaker":"西本委員","kind":"質問・要望","question":"それはそれでいいと思うんですけれども、別に白と黒にしなくてもいいのかもしれないんですけれども、どういう意向なのかということはもう少しお話をしていただきたいなと、いろいろな意見があったということになるとは思うんですけれども、ある程度、この文面からはどっちなのかなというのがちょっとわからないので、その辺はいかがですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"区から提示されているのも非常にまだ漠然としている内容で、これでちょっと議論しているというのは、私には不思議な気がするんですけれども、やはりきちっとしたＴＯＣの計画書が今ここにありますと、こういう工事でこういう内容でこういうふうに進みますと、ただ漠然と１０年間ということならば、それはやはり反対せざるを得ませんけれども、こういう内容でこうなんだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"私はちょっと理事者に２点ほど質問したいんですけれども、前回の委員会のときに説明いただいた部分のちょっと改めて確認なんですが、ＰＴＡと町会連合会に説明会を開いたというお話をいただきましたよね。その際、説明をした内容、それをちょっと改めて確認をしたいんです。この２つです。","respondent":"榎本行財政改革担当課長","answer":"その説明した内容につきましては、当委員会で説明した内容を町会長会議でも説明しましたし、学校などでも、その内容に基づいて説明をしています。ただ、学校を移転、新築することと、その跡地については貸し出すということで説明をしたところです。","voiceIndex":17,"id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"その貸し出すことを了解する、いいのではないかと、考慮に入れましょうという、そこの区側の判断なんですが、この間伺ったところでは、地域の商業の活性化を、振興を衰退させてはならないことだとか、改築の経費を一部肩がわりしていただけるということだというふうにあるわけですが、今後、同じような問題が出たときに、民間から公有地の活用をしていただきたいという申し出があったときには。","respondent":"榎本行財政改革担当課長","answer":"それで、そういう貴重な財産という観点から、中長期的な見通しも含めた上で考えていくというのがもちろん大きな考え方であって、今後もこういうケースが出てくるかどうかというのは、そのケースごとにそれぞれ考えるということでありますので、実際上。","voiceIndex":19,"id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"そうすると、民間に貸し出すことも、これからはケース・バイ・ケースだけれども、そのときの条件によるけれども、あり得るということなんですか。最後の確認ですけれども。","respondent":"榎本行財政改革担当課長","answer":"それは多分、当分は出てこないと私は考えておりますけれども、そういうことも含めて、区が財産として持っていればいいのかどうかという判断のもとに、最終的にどういうふうに使っていくかという形ですので、貸し付けということで区の住民の方の負担を少なくするというのであれば。","voiceIndex":21,"id":"exchange-016"},{"speaker":"三上副委員長","kind":"質問","question":"今の話をちょっと引き継ぐような話になるんだけれども、逆の立場というのもありましたよね。要するに、品川区が何かをやりたいと考えて、民有地を借りるという、そして、そこのところを借りて、それで品川区の事業を行うということだって過去あったと思うんです。どうですか。","respondent":"榎本行財政改革担当課長","answer":"民有地を借りているところもありますし、国有地を借りているところも今現在もありますので、そういう前提のもとに公の施設等が設置されているところは多々あります。","voiceIndex":23,"id":"exchange-017"},{"speaker":"三上副委員長","kind":"質問","question":"ですから、そういった面があって、過去の事例としては、もう少し丁寧にやっぱり説明を理事者側はしなきゃいかんと思います。そういった具体的な例を挙げながら、過去にはこういったこともありましたということを、そういう事実は、そういったことは皆さん認識した上で、またこういう１つの結論を導き出していくということだってあり得る話ではないかと、こういうふうに思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":25,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"それぞれ会派からいろいろ説明はありましたけれども、全体を聞いている中で、もっと住民との話し合いの部分を大事にすべきだというところではそれぞれ一致しているのかなと思ったんですけれども、この上に立って、もしお考えがあればちょっと詳しく聞かせていただければと思ったのが、自民党品川区議団の会派の(2)と(3)はそれぞれほぼ共通するんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-019"},{"speaker":"伊藤副委員長","kind":"質問","question":"ただ、例えば、全く初めてのことですから、先ほども言いましたように、そういう事務的なことの連携、ＴＯＣとの連携、いろいろな意味で、そういうふうに地域の連携をとってくださいということですので、例えば、その中身は町会、自治体への説明とかが当然入ってくると思われます。ですから、大きな意味で連携という表現をさせていただいたものですから、これと縛りをかけるということではないです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-020"},{"speaker":"中塚委員","kind":"意見","question":"この委員会でも防災のことが若干議論になっていましたけれども、もう少し補足的にお考えを聞かせていただければと思った点が、しながわ自民党の5)の防災拠点としての機能を充実することとありますけれども、防災拠点は水害、地震、いろいろありますけれども、ちょっとここだけもう少し詳しく聞かせていただければ、どんな防災かと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":28,"id":"exchange-021"},{"speaker":"本多委員","kind":"意見","question":"日野中学校の跡地に第一日野小学校ができることによりまして、その建物自体が、例えば耐震性にすぐれているものができる、それだけでも防災性が上がるわけです。移ったときに、合わせて移ったほうがいいのか、そういうことも視野に入れて、消防団に限らず、地域で何かあったときに、事が起きたときに対応できるそういうシステムを総合的に視野に入れて、防災機能を上げてほしいということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":29,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとお聞きしたいんですけれども、今回、貸し出すということで、第一日野小学校の跡地のことで、区の姿勢をお伺いしたいんですけれども、ＴＯＣ、それから中を借りているテナントにとっては、今回はいろいろな意味でメリットがあると思いますけれども、その近隣に住んでいる地域住民、企業じゃなくて、生活している住民にとっては、今回。","respondent":"上野都市開発課長","answer":"その営業継続ということは、近隣のご利用されている方々がずっと継続してそういう購入などが行えるということを想定しているものですから、そういう面にとっては、周辺のご利用されている方々のメリットがあると、ずっとそれが中断することなく、そういう日常生活も、購買とか。","voiceIndex":30,"id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"それこそ電話も聞こえない、話し声も聞こえないという状況も、本当に直近にお住まいの方ならまさにそういう状況になります。車も頻繁云々、その辺は交通整理等々でまた努力するしかないんですけれども、震動と騒音に対して、これだけ長期間近隣住民に影響を及ぼす、つまり、これは精神的また肉体的にもかなりのダメージをこうむると思われるんですけれども、この辺についてどのようにお考えでしょうか。","respondent":"岩田まちづくり事業部次長","answer":"ただ、まだまだあらあらの案の段階ですので、今の段階ではおおむね１０年ぐらいではないかという程度ですので、今後、細かい詰みがなされてくれば、当然、委員のおっしゃるように、工事中の迷惑というのはどんな工事であっても周辺の方にはかけてしまいますので。","voiceIndex":32,"id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"まさにそれはある意味で、区としてやはりそちらの面も考えるということは大切なことだと思うんですけれども、ただ、私が訴えているのは、今、確かに雑駁、もう本当の概算の建設期間ということですけれども、やはり区の公有地、区有地を貸すわけですから、それならば、できるだけ騒音や震動に悩まされない、その期間が短いような方向でやはりＴＯＣに働きかけて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-025"},{"speaker":"南委員","kind":"質問","question":"ですから、これからその辺をどういうふうな形で、急いで決めなくてもまだ時間は計画も漠然としたものでしかないという話だし、残された時間は決して少ないということではありませんので、もっと十分意見を聞いて判断をしていくべきではないかなというふうに、公有財産で初めての経験ですから、慎重の上にも慎重を期すということが大事だと思うので、そちらの考え方と、それから。","respondent":"榎本行財政改革担当課長","answer":"要は、ここのスタート地点が決まらない限りは、次、ずっと後々影響を引く形になりますので、ここの部分である程度大きな方針が立った上で、あとは個別にその都度わかる範囲で詳細なものを説明をしていくという段階に立っていると認識をしております。","voiceIndex":35,"id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、今のところは、もしわかる方がいらしたら、ぜひ教えていただきたいと思います。だから、改めてちょっとそこについては、もしご見解があればおっしゃってください。２点です。","respondent":"新美企画部長","answer":"１点目の三菱マテリアルの件については、直接担当でございませんので、今日はちょっと申しわけありませんが。で、２点目のところ、今のご発言については、特に見解は先ほど申し上げたとおりです。","voiceIndex":37,"id":"exchange-027"},{"speaker":"南委員","kind":"意見","question":"１つは、商業振興だとおっしゃるけれども、それも大きな意味での公共性はあると思いますけれども、しかし、今までやってきたものとは絶対的に質が違いますよね。したがって、今までやってきたからということでくくって、こういうことを経験則にしてしまってはいけないんじゃないかなということをちょっと注意として私は持っておきたいと思うし、そういう姿勢は区としても失っていただきたくないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":39,"id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"確認したいんですが、ＴＯＣから１０年から１２年の工事期間という話がここに出ているんですけれども、それは説明が雑駁なところがあったのか、要するに、１０年間絶対にかかりますよという表現で説明があったのかということを教えていただきたいんですが。","respondent":"上野都市開発課長","answer":"まだその大規模改修計画の内容も固まってございませんので、現段階ではおおよそ１０年程度は最低限かかるのではないかということでございまして、大規模改修計画の中身が明らかになってくる中で、さまざまな工夫などもして。","voiceIndex":40,"id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"これはぜひ求めていってくださいということをまずお願いしておきます。例えば、将来的にはＴＯＣとのそういう契約をして、いつごろ区切っていくのかとか、それから、この利用というか、全体をいつごろまでまとめていくかとか、もう来年度予算の編成時期に入っているでしょうから、今後の見通しというものを、雑駁でいいんですけれども、教えていただければと思うんですがいかがですか。","respondent":"榎本行財政改革担当課長","answer":"来年度予算の関係で行きますと、施設の基本設計という形に入らなくてはいけないということで、前に整備スケジュールのところでお示しした１８年度中に基本設計をしていくというところの予算が、１８年度で計上をしないとスタートができないという形になっています。","voiceIndex":42,"id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"質問","question":"そうすると、基本設計を１８年度中に決めていくということであれば、これまでの間に、設計はすぐできるんですけれども、その事務的なこういうつながりの契約とか、ＴＯＣの費用負担の問題とか、そのことについてのリミットといいましょうか、それはどういうふうに考えているんでしょうかということを聞けますか。","respondent":"新美企画部長","answer":"先ほどから申し上げていますように、日野中学校跡地の利用計画、小学校を移転するということを含めて、それからＴＯＣにその跡を貸して、その全体の財源計画、このスキームの中でこの計画を実現していこうですので、ＴＯＣとの細かな詰めは、というか、大方針として。","voiceIndex":44,"id":"exchange-031"},{"speaker":"伊藤副委員長","kind":"確認","question":"そうすると、来年度予算は我々が最初に審査しますからあれですけれども、計上する計画を持っているということですね。それから、民間に貸し出す話の１つで確認なんですけれども、サンピア商店街の裏にある駐車場、あれは品川区所有の土地ですよね。あれはたしかイトーヨーカドー等に貸し出していると思うんですが、その確認をいただければと思います。","respondent":"岩田まちづくり事業部次長","answer":"全体として、区で持っている財産、特に不動産の場合は、普通財産と行政財産と２つありまして、委員がご指摘のサンピアの裏の区が持っている、昔、原っぱ公園であった跡地につきましては、まちづくり事業予定地という行政目的をまだ消しておりません。","voiceIndex":46,"id":"exchange-032"},{"speaker":"伊藤副委員長","kind":"確認","question":"ただ、私たち自民党品川区議団としては、市場化テストとか、民間の活動をいろいろ当然やっていけると考えていますので、そういう今までの経験則を踏まえた上で、プラスアルファの新しい事業に取り組んでいくわけですから、やはり慎重には慎重を重ねた上で、どうしても癒着とか、それから、今回、ＴＯＣから行政に対してお金が相当動くでしょう。それを私たちはまとめなきゃいけないですので、その確認だけ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-033"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々ネット・無所属は、やはり住民にも、ここで生活しているだけの人もいるわけですから、その辺も考えて公有地を貸すということが大前提だと思っていますので、何度も納得できない回答かもしれませんけれども、そこはちょっとご理解願いたいなと思います。つけ加えさせていただければ、本来なら、今ここに五反田ＴＯＣの建築計画、おそらく設計もでき上がっているかと私は思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-034"},{"speaker":"伊藤副委員長","kind":"意見","question":"そうすると、先ほど企画部長から説明があったように、これから具体的な計画がどんどん出てくる、その案が提示された中で、ネット・無所属としてこれは賛成できるということになるならば賛成するということですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":50,"id":"exchange-035"},{"speaker":"中塚委員","kind":"質問・要望","question":"そこでちょっと伺いたいんですけれども、今、ＴＯＣといろいろな、ここが決まったら具体的な詰めの部分を進めていきたいというお話がありましたけれども、実際、それを明らかにして、１つの形として報告をされるのに、大体どれぐらいの時間といいますか、１年なのか、２年なのか、ＴＯＣとの協議、またＴＯＣ自身ではまた設計をつくる期間、どれぐらい時間がかかるというように区自身は見通しているのか。","respondent":"上野都市開発課長","answer":"特別委員会において、さまざまな議論をいただきまして、各会派別の意見をちょうだいしているところでございまして、おおむねこの方針に沿った形で進めてよろしいですれば、その詳細な協議をＴＯＣと進めていきますけれども。","voiceIndex":54,"id":"exchange-036"},{"speaker":"中塚委員","kind":"質問","question":"来年度早々ということは、その詰めの部分も合わせて、大まか１年ぐらいで双方の議論が進む、それぐらいの話し合いの期間を見込んでいるということなんでしょうか。ちょっともう一回教えていただけますか。","respondent":"上野都市開発課長","answer":"協議はずっと並行して進められまして、その中で貸し出し内容ですとか、貸出条件ですとか、そういったものの協議は並行して進められるわけですけれども、先ほど申し上げたのは、基本的な大枠というか。","voiceIndex":56,"id":"exchange-037"},{"speaker":"中塚委員","kind":"質問","question":"そうなると、日野中学校の敷地を、壊して、新しい第一日野小学校をつくって開校するのが、区の大まかな予定だと２１年度開校、４月ぐらいなんですかね。雑駁に４年間ぐらいですか。仮に１年間それを続けた上で、また一定の方向を出してからでも、ＴＯＣと協議をして、いわゆる今の第一日野小学校の場所が更地になった後の話、まだ４年以上あるわけですから、まだ時間的にそこは決まっていないと思うんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問","question":"それぞれの会派から意見が出ておりまして、例えば、７つの会派で共通する項目があれば、その項目を委員会として出せるんですが、私が思うに、共通する項目がありませんので、このまま委員会としての、何ていうんですか、委員会の意見というのは難しいと思いますので、これがそのまま意見というか、報告になるのではないのかなと私は考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-039"},{"speaker":"中塚委員","kind":"質問","question":"ただ、この前提として、こうやって今日集中的にこの問題を議論しているのも、区のほうから計画案を出したときに来年度予算を見越している中で、委員会として一定の、表現はそれぞれありますけれども、やっぱり区の方向に対して、ちょっと待ってくれと、もっと住民の意見を大事にしてくれとか、防災の面を大事にしてくれと、住民との連携を大事にしてくれと、そういう意見が出ているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-040"},{"speaker":"本間委員","kind":"質問","question":"今、中塚委員の話初めて聞きました。非常に前向きなまとめ方のように思います。この共産党の会派別意見一覧を見ると、今の文言は一言も出ていないんですけれども、そのような部分での考え方として、共産党の考えはまとめてよろしいんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":65,"id":"exchange-041"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、会派としての意見は、今のこの計画は一度白紙に戻して、それぞれの会派の出された意見を尊重する中で、時期的にも、実際あそこが更地になるのは大まか４年後ですから、住民の意見をまとめるのは時期的にも足りると思うし、実際にＴＯＣの詰めの協議を行ったとしても、１年ぐらいでその協議が進んで形が出るということであれば、なおさらまだそういう時間はあるのではないかというのが僕らの見解です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":66,"id":"exchange-042"},{"speaker":"本間委員","kind":"質問","question":"この白紙に戻るという部分に戻っているわけですけれども、先ほど、しながわ自民党の本多委員から話が出た中で、これだけいろいろばらばらでまとめ切れないというふうな話が出ている中で、共通事項があるじゃないかという中に、やはり前段も説明がございましたように、新しく第一日野小学校を建てて、そしてそこに幼保一元化施設として移る部分もまとまっているんじゃないかと私は受けとめたものですから、今。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-043"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、そういう計画をするに当たっても、やっぱり区民の意見を十分に聞いた上で決めていくべきだと、そういう立場をとるものです。ですから、そこがそういう表現になり切れているかどうかは、それはそれとしても、趣旨としてはそういうことだということですので、だから、移転後の日野中学校跡地の移転利用計画については、第一日野小学校を移転していくということについて反対ではないということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-044"},{"speaker":"大沢委員","kind":"質問","question":"それも思いとしてお話ししておくので、正副委員長には別物に分けてまとめていただくような形をとらないことには、これを１つでまとめろといっても絶対無理な話で、第一日野小学校跡地について書いてある、皆さん会派ずつのご意見があるわけですから、日野中学校跡については一定のラインは引けますけれども、第一日野小学校についてはもう皆さんばらけちゃっている部分がある。","respondent":"宮崎委員長","answer":"いずれにしても、今、いろいろな論点が、それはいいか、悪いかというようなご意見って多いから、第一日野小学校の新築移転をどう考えるのか、ＴＯＣへの貸し出し、それをどう考えるかというようなことがあるのと、貸し出した後、その後の活用をどう考えるのかということが。","voiceIndex":69,"id":"exchange-045"},{"speaker":"西本委員","kind":"意見","question":"日野中学校については、一定のというところ、ある程度同様な意見というのはまとめられると思うんです。当然、その意見の違うところ、考慮をしてほしいところというのはいろいろ出ていると思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":71,"id":"exchange-046"},{"speaker":"南委員","kind":"意見","question":"今、西本委員のおっしゃったことも、基本的にはさっき委員長がまとめられたことと同じだと私は理解しているので、論点をもっとはっきりさせて、そこでどんな意見が出たかということでまとめていただいていいんじゃないかと思います。それは正副にお任せしてやっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":72,"id":"exchange-047"},{"speaker":"須貝委員","kind":"提案","question":"先ほど本多委員からご提案があったんですけれども、ほとんど各会派をまとめるとしても、現実論、これはなかなか難しいのかなと。","respondent":"宮崎委員長","answer":"今、皆さんに今後のまとめ方等、委員会としての取り組みの意見もいただきました。いろいろあったんですけれども、一定のやっぱり取りまとめをというのがちょっと大方の意見だったかなと思います。その中の今日お配りしてありますこの意見の一覧の活用だったんです。","voiceIndex":73,"id":"exchange-048"}]},{"id":"topic-02","title":"密集住宅市街地整備促進事業、二葉３・４丁目、西大井６丁目の地区防災まちづくり計画（案）説明会等について","agenda":"密集住宅市街地整備促進事業、二葉３・４丁目、西大井６丁目の地区防災まちづくり計画（案）説明会等について","exchanges":[{"speaker":"本間委員","kind":"意見","question":"その部分の取り扱いは、この部分の点線の最初のところを歩いたところで見かけていますが、その件について、今後どのようにしていくのか、ただ建て替えでセットバックしてもらったけれども、電柱がそのまま残っているという部分についてのお考えをお尋ねします。","respondent":"伊勢住環境整備担当課長","answer":"ただ、そこの部分だけじゃなくて電線でつながっているので、結構その位置をそこだけ直すというのはなかなか難しいということと、それから、そこにお住まいになっている方が、あまり接近しちゃうと、例えばベランダとかというものに近づいていきますので。","voiceIndex":82,"id":"exchange-049"},{"speaker":"本間委員","kind":"質問","question":"いろいろなケースがあると思いますけれども、特にこういうふうにして重点細街路という位置づけで指定された地域につきましては、今のお話ですけれども、やはり連動した形で進められていかないと、もう変な話だけれども、時機を逸したらなかなかというようなことにもなろうかと思いますし、それは個々のケースでいろいろあるかもわかりませんけれども。","respondent":"伊勢住環境整備担当課長、松代管理工事課長","answer":"先ほども申し上げましたけれども、設置者が移転しないことにはどうしようもないわけですので、そういう面では積極的にこの事業の説明を十分して、設置者に対して理解を求めて。当然のことながら、そこに、もともとは狭いところにあったわけですけれども、広がるわけですから、そういったところはきちんと適切な場所に移設するように我々も指導をきちんとしていきたいと考えています。","voiceIndex":84,"id":"exchange-050"},{"speaker":"本間委員","kind":"質問","question":"そうしていただければいいんですが、そうすると、その本人の、あるいは対象となる家の申し出によって、そういう希望が生じた場合には、対応をしていくということでよろしいんですか。","respondent":"松代管理工事課長","answer":"移設をする場所ということで、その話だと思うんですが、基本的には、その占用をしております占用者が、周辺のところに１軒１軒当たりまして、了解を得て、そこに移すということになろうかと思うんですが、どうしても。","voiceIndex":87,"id":"exchange-051"},{"speaker":"本間委員","kind":"質問・要望","question":"自分のうちの敷地の範囲内での、今度はよその敷地にまたがって移動するというのはなかなか困難性があるというか、感情的な問題も発生しますのであれですけれども、同じ建物を所有しているその敷地内で移動するというふうなことも含めて、いろいろケース・バイ・ケースであろうかと思いますが、お困りの方、苦情がある部分も中には聞いておりますので、そういう部分での対応を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-052"},{"speaker":"本多委員","kind":"質問・要望","question":"３年前に２９号線の見直しを求める請願が区議会全会派で採択されている経緯もありますし、その辺でここを本当にこれをこのように計画案に載せて進めていくのか、その辺をちょっと確認をさせていただきたいんです。","respondent":"伊勢住環境整備担当課長","answer":"細街路等とは性格を異にしていますけれども、やはりこの道路といいますか、この幅の空間といいますか、もしこういうものができるとしたら、延焼遮断帯として非常に効果があるということで。","voiceIndex":90,"id":"exchange-053"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、関係部局に働きかけますということなんですが、今、都市計画道路の中にも、地図上でも網だけはかかっていて、これからの１０年間とかというプランでも都のほうで全く手をつけませんよということになっちゃっているんですが、この関係部局に働きかけるというのは具体的にどういうことなのか、ちょっともう一度教えていただきたい。","respondent":"伊勢住環境整備担当課長","answer":"道路という形で整備するというのはもちろんそういうことなんですが、一定の空間として整備できないかということも、今、研究しています。","voiceIndex":92,"id":"exchange-054"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっともう一度、拡幅されるのがどことどこなのかというのを、それで、どれくらい拡幅されるのかというのをちょっと確認の意味でもう一回教えていただきたいと思います。というのは、やっぱり決めていくときに、そういう住民の方たちの思いというのを受けとめながら判断していく必要があると思うので、ぜひ、どうなっているのかを教えていただきたいと思います。","respondent":"伊勢住環境整備担当課長","answer":"２９号線につきましても、ここはどうなるんですかということで、先ほど申し上げましたように、議会での請願採択と、それから、優先整備路線となっていないですというようなお話ですけれども、やはりこの密集事業、どういうことかというと。","voiceIndex":94,"id":"exchange-055"},{"speaker":"南委員","kind":"質問","question":"確かに延焼遮断帯をつくる一定の空間がざっとあるということはすごく効果があるんだろうと思うんです。２９号線を整備して延焼遮断帯をつくる以外に、何か方法というのは考えられないんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"２９号線の整備以外にどういうものがあるかというようなご質問ですけれども、まさに今説明しましたこの計画図案あるいは概要に載っているものがそのものです。それと、２９号線との関係ですけれども、あわせてこれをやればさらに安全性が高まると、こういうような位置づけです。","voiceIndex":96,"id":"exchange-056"},{"speaker":"南委員","kind":"質問・要望","question":"そうしたら、その辺の数字を、どのくらいの住民の方々がおられるのかがわかったら、後ででいいですけれども、教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":98,"id":"exchange-057"},{"speaker":"西本委員","kind":"質問","question":"これで承認が得られると、ある程度の補助金とかというのが出てくるのか、その辺はいかがでしょうか。ただ単に建て替え促進といいましても、何もない状況で建て替えと言われましてもなかなか難しいでしょうし、たまたま建て替え時期に来たからという人はよろしいかもしれないんですけれども、その辺の財源も含めた計画はどうなっているんでしょうか。","respondent":"伊勢住環境整備担当課長","answer":"あと共同建て替え、一緒になってというようなことですけれども、できるだけこの１０年間でご計画いただいて、やっていきたいと。もっとも、最近建てたという方は、当然１０年間の中ではおさまりませんので、その辺は難しいだろうということが挙げられます。","voiceIndex":99,"id":"exchange-058"},{"speaker":"西本委員","kind":"質問・要望","question":"多分、今はどこを買うかどうかわからないという状況なので、今は難しいと思いますけれども、安全面も含めて公園緑地をつくっていただきたいなというふうに、これは要望になると思うんですが、考慮していただきたいと考えています。それから、建て替えについてはアパート、共同住宅ですか、これは予算が出るんですか。ある程度促進をして、何かしらのお金が出る、補助金が出るという考えでよろしいですか。","respondent":"伊勢住環境整備担当課長","answer":"アパート建て替えですけれども、これにつきましても、細かいいろいろな基準があるんですけれども、例えば共同の施設整備費だとか、国や都と若干違うんですけれども、大枠で行きますと、その補助金対象の２分の１が国で、４分の１。","voiceIndex":101,"id":"exchange-059"},{"speaker":"西本委員","kind":"質問・要望","question":"そういう周りの環境でどういう広場になっているのかというのは、ある程度周りの立地条件を考えた上でちょっとつくっていただかないと、かえって非常に危険な区域になってしまいますので、それを考慮して計画をしていただきたいというふうに要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-060"},{"speaker":"中塚委員","kind":"質問・要望","question":"改めてちょっと伺いたいのは、まちづくり協議会の活動や、この密集事業において、住民参加で住民合意のこの位置づけを品川区がどう考えているのか、改めてちょっと教えていただきたいんです。","respondent":"伊勢住環境整備担当課長","answer":"ただ、その計画をつくるに当たって、やはり地元の方のご意見を聞いたり、あるいは地元の方にこの事業を周知するために、懇談会等をつくって、皆さんの意見を聞きながらやっていったほうがいいだろうということで、この懇談会、ほかの地区もそうですけれども。","voiceIndex":106,"id":"exchange-061"},{"speaker":"中塚委員","kind":"質問","question":"今の説明にありましたけれども、つくるに当たって地元の方の意見や、懇談会を通じて意見集約をするというお話がありましたけれども、ここで二葉は３・４丁目、西大井６丁目地区のまちづくり協議会となっていますけれども、これのこれまでの経過を伺っていますと、まず３・４丁目のほうの協議会が先行する形で、６丁目のほうが９月までは準備会で、１０月からは懇談会という形で２回ですよね。","respondent":"伊勢住環境整備担当課長","answer":"そういう面から立ち上がり時期がおくれたですけれども、やはりこの趣旨を十分説明した上、危険地域は危険度調査ではもう出ているんですけれども、特に避難の関係だとかとあるわけですけれども。","voiceIndex":108,"id":"exchange-062"},{"speaker":"中塚委員","kind":"質問","question":"一方それとはちょっと離れる形で、西大井６丁目は準備会が３回、懇談会が２回で、もっと不十分な点が残っていると思うんですけれども、ここはもう一度伺いたいんですけれども、これで十分歩調のとれた、３町会が一体となった１つの事業として成立しているのかなというのがちょっと気になるので、もう一度。","respondent":"伊勢住環境整備担当課長","answer":"もし、やっていくうちに、ここもどうかというようなことがございましたら、この計画をしかるべき時期にそれを盛り込むような形の変更ということもありますけれども、現在のところは不十分な会合とか、あるいはそういう内容というようなことではないと認識しています。","voiceIndex":110,"id":"exchange-063"},{"speaker":"中塚委員","kind":"質問・要望","question":"住民の方への説明や合意というのは、どこまで行けば完璧かというよりも、常に求め続けるものだとは思うんですけれども、先ほども補助２９号線の話が出ていましたけれども、過去の経緯を踏まえても、この地域の方が補助２９号線に対して異を唱えて、運動を。なぜでしょうかね。","respondent":"伊勢住環境整備担当課長","answer":"ただ、期間が少なかったですので、４月に予定どおりこの事業が開始した後も、懇談会あるいは別の会だかちょっとわかりませんけれども、そういう会を持ちながら、密集事業を進めて、もし、変更すべきものが出てきた場合には、それを考えていくというような腹づもりでおります。","voiceIndex":112,"id":"exchange-064"},{"speaker":"南委員","kind":"質問・要望","question":"さっきちょっと聞きそびれちゃったんですけれども、この説明資料の中の２の今後の予定の3)の整備計画大臣承認申請及び事業計画大臣同意申請予定という、これをちょっと詳しく教えていただきたいのと、この関係でなのか、ちょっと私は理解できなかったので、任意事業として進めるというふうな説明をされましたよね。その任意事業というのはどういうものなのか、そこを教えてください。","respondent":"伊勢住環境整備担当課長","answer":"任意といった場合は、例えば強制的に土地を買収して、できない場合は立ち退きまでしていただくというようなことではなくて、あくまでも土地所有者あるいは借地権者の理解と協力のもとに、６メートルに拡幅する場合に、いろいろなケースがあると思うんですけれども。","voiceIndex":114,"id":"exchange-065"},{"speaker":"南委員","kind":"確認","question":"それはそれとして私は理解できるんですけれども、最終的に、発表してこれから進めていくよというふうに説明会を打ち出すに当たって、少なくともまちづくり協議会の皆さんの理解と合意は得られたという確認をしているということですか。","respondent":"伊勢住環境整備担当課長","answer":"したがいまして、合意というような表現では使いませんけれども、いろいろなお話が出た中で、区がまとめていくというような形で、そして、拡幅するのんき通りの点につきましては、区から提案したものですけれども、皆さんには事前に何とかお知らせして確認してきたということで。","voiceIndex":116,"id":"exchange-066"},{"speaker":"須貝委員","kind":"意見","question":"これから防災まちづくり計画ということで説明会を順次行っていくということなんですけれども、一番やはり問題になるのは、その道路に面している１軒１軒の方たちだと思うんですけれども、この方たちに対して、今回説明会のお知らせということで、個別に区の職員が回るのか、町会の役員が１軒１軒手渡して、こういうことがありますということで行うのか、それともただポスティングするだけで。","respondent":"伊勢住環境整備担当課長","answer":"それと、全体の、皆さんお集まりになりますので、ここが建物がかかっていると、測量はしていないですから正確なことは言えませんけれども、あまり個別の説明はこの日はしない予定です。","voiceIndex":118,"id":"exchange-067"},{"speaker":"宮崎委員長","kind":"質問","question":"ちょっと私から二、三伺いたいんですけれども、のんき通りと、あと、杜松小学校に向かうところを６メートルに拡幅ということなんですけれども、大体何軒ぐらいが対象というか、要するに、ずれなきゃいけないというのは何軒ぐらい対象になってくるのかと、あともう１つ、立会通りと三間通りの間のこの赤の点線のところの道路でも、ここも今、建て替え時にセットバックをやっていますけれども。","respondent":"伊勢住環境整備担当課長","answer":"のんき通りに面している棟数ですけれども、３１軒、それから、のんき通りから杜松小学校のところは３４軒というふうに、現在、把握しておるところです。それから、申しわけございませんが、細街路のほうはちょっと詳しい資料がないので、何軒ということは、申しわけございません。","voiceIndex":121,"id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6314#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":52129,"voices":130}},{"id":"h17-20051201-14","meetingId":"h17-cm12","date":"2005年12月1日","dateIso":"2005-12-01","committee":"行財政改革特別委員会","time":"午前１０時０７分～午後２時２７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を80件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"行財政改革に関することのうち、民間委託等に関すること","agenda":"行財政改革に関することのうち、民間委託等に関すること","exchanges":[{"speaker":"沢田委員","kind":"質問・要望","question":"具体的に指定管理者の候補者を選ぶ段階で、どういう周知をしているか。今度はかなりの部分がこれまで管理をしていた財団あるいは社会福祉法人に移行します。これから民間やＮＰＯまで広げていこうとすると、どういう公募をするのか教えていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"今後、公募する場合につきましては、候補者を実際に選ぶ段階でホームページ等を使ってやっていきますけれども、今回は基本方針に定めたとおり、現行事業者を基本としていくということで、今回については特に周知という形はとっておりません。","voiceIndex":5,"id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"今後についてはホームページなどでこの管理を募集するよと広く呼びかけると。もう１つ聞きたいのは、今度の指定管理者を選定するに当たって、議決をするというふうに法律が変えられましたけれども、議決をするという意味は、なぜ今まで庁内でやっていたものを議決をするというふうになったのか、その根拠、考え方について説明願いたいんですけど。","respondent":"榎本行財政改革担当課長","answer":"それに対応するように、逆に指定管理者の指定に関しては、議会の関与という形で入ってきております。その議会の関与につきましては２段階ございまして、まず１つ目としては、指定管理者制度を公の施設に適用するよという形の条例の改正の段階で１つ議会の関与があります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"沢田委員","kind":"質問・要望","question":"私の考えでは、候補者を議会が選定する以上、議会の責任が問われると思うんですが、先ほどの私の質問に、ちょっとそこらがまだ答えられていないんですが、なぜ今度新たに指定管理者制度の中で議会の議決をするようになったのか、具体的な理由を、これまで工事や何かの契約で、一定額以上は議会に出したと同じだと言ったんですけど、もうちょっと違った意味合いがあるんじゃないかと思うので。","respondent":"榎本行財政改革担当課長","answer":"例えば仮にですけれども、その業者がなくなってしまって、契約が履行されないという形になったとしても、その議決に関して議会は責任を問われることはありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"今の話を聞きますと、議会の議決はお飾りだと。私は、今度の議決を経て、体育館だとか、特養ホームだとか、きゅりあんだとか、本来行政がやるべきものを民間企業やＮＰＯまで拡大した場合に、先ほど基準の中で、サービスの向上と経費の節減と２つの柱を挙げた。その上で特に大事なのは平等性の確保だとおっしゃいましたよね。検討ができるような資料を出すべきだと思いますけれども、そこはいかがでしょうか。","respondent":"榎本行財政改革担当課長","answer":"今回は基本方針のもとで、１つしかないという部分はありますけれども、その部分のきちんとサービス内容等がわかるような説明をいたしますし、各選定理由等の中にも、どういうところですぐれているのかという形で書いてありますので。","voiceIndex":11,"id":"exchange-004"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は今度の、本来行政がやってきたやるべき管理の仕事を民間にやる場合には、よほど慎重でなければならない。それは法律上、例えば損害みたいなのをやった場合にはそうかもしれないけれども、それを議会がどう審査したのだということは、問題が起こった場合、当然後ほど区民から厳しく問われる可能性があるので、私は今までの形どおりではなくて、必要な資料を出していただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":13,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"これでは到底中身が理解を得られないのではないかなと思っています。この資料からすると、行政の方が判断をした中身を見て納得してくださいという中身でしかないのではないかなと受けとめてしまうわけなんですけれども、資料提供があって初めて議会が行政と対等な意味での評価ができると思うんですけれども、この辺についてはいかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、行政と議会とどのような分担をしていけばいいのかというご答弁があったんですけれども、ぜひこの辺を今日この場でも論議をしていただきたいなと思います。私はどういう分担をするのかという大前提に、同じ土俵というか、同じ情報が得られていなければ、対等には話し合い評価はできないと思っていますので、ぜひこの場でこの点も論議をしていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-007"},{"speaker":"藤田委員","kind":"質問・要望","question":"１つ質問なんですが、今後、設置者である区と管理者の運営に当たっての関係なんですけれども、これは例えば今、議論しますのは、あくまでも行政の立場に立っての話を今やっているんですが、一方、区民、利用者に対してどのような耳を持っていくかというのは一番大事な話ではないかと思うんですが、１つここで区民サービスの向上と経費削減等を図るとなっていますが、この経費削減を例えば図り過ぎちゃって。","respondent":"榎本行財政改革担当課長","answer":"利用者の部分の苦情等につきましては、当然第一義的には運営者である指定管理者という形になりますけれども、設置責任者としての区はフォローなりカバーをしていくという形で、今までも管理委託制度という形で同じようなしくみで委託運営をやっておりますので。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問・要望","question":"そうしますと、利用者が、例えば今までのやり方と今度の指定管理者になりますと、やり方が全然違うと。例えばの話、一つひとつのやり方が今までのやり方と違うんだと。それともう１つは、こうしてもらいたいんだという要望ですよね。利用者は管理者に対して要望を直接言っていくのか、区の方に言うのか、それとも両方へ言わなきゃいけないのか、この辺をお願いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"そういう部分につきましては、モニタリングシステムとか、評価のシステムの中に組み込んでいって、定例的なそういう苦情なり要望なりの部分が、どう次の計画に改善して盛り込まれるかというものをしくみとして入れ込んでいくという形を、今後工夫を図っていきたいです。","voiceIndex":21,"id":"exchange-009"},{"speaker":"藤田委員","kind":"意見","question":"これはやっぱり１つの大事なチェック機関だと私は思うんですが、先ほどの議会との関係といいますか、こうした情報を議会にも適宜出していただいて、そこで議会として今度は今の経過をそれぞれが議論をし、区としての立場、指定管理者としての適正な業務内容、そして住民の声というのを、我々はそこで議論していくと、このようになっていくと私は思うんですね。これは意見ですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":23,"id":"exchange-010"},{"speaker":"林（宏）委員","kind":"確認","question":"最初にちょっと、説明文の中でよくわからないところだけ確認をしたいと思いますけれども、この大きい表の一番上にあるきゅりあんの利用料金制の、今回導入というのが説明にも書いてあるんだけど、今も料金はいただいている部分があるでしょう。その辺とどうなのか。この４文字だけではちょっとわからないので、詳しく説明ください。","respondent":"榎本行財政改革担当課長","answer":"この利用料金制というのは、例えば区民集会所の施設使用料を考えますと、施設の使用料として区が歳入をするというのが普通の使用料の歳入だと。それを利用料金制の場合については、管理団体の方が収受をして、その部分を精算していくという形になっております。","voiceIndex":24,"id":"exchange-011"},{"speaker":"林（宏）委員","kind":"確認","question":"今回、導入という言葉が適切かどうか。これからのことを確認していきたいんですけど、今の料金の場合も、我々に予算案が提示されて、予算を決めていきますよね。そうすると、例えば５月、６月からしか料金が変えられないとか、そういう縛りが、業者の方は４月１日からやりたいのにできないという、その辺のタイムラグとか、そういうことについてはどういう検討をされてきているのか、それだけ説明ください。","respondent":"榎本行財政改革担当課長","answer":"実際に今までの料金改定の部分につきましては、経過措置期間というのを必ず設けておりまして、一定の場合には可決が３月下旬という形になりますので、実際に料金を変えるのは大体３カ月もしくは６カ月程度の経過措置を置いた後で変えるというのが。","voiceIndex":26,"id":"exchange-012"},{"speaker":"林（宏）委員","kind":"質問","question":"５年契約をしちゃったら、５年間はそこに任せっきりということになるようなニュアンスに、料金は上限を決めてあるんだから、その範囲でやっていくのは勝手ですよとか、そういうふうになってくると、１年ごとに、最後に書いてあるモニタリングとか、そういうことが何かむなしい文字になるんだけど、１年ごとにやっていくということをもう少し、どういうしくみでやっていくのかについての説明と、それから。","respondent":"榎本行財政改革担当課長","answer":"料金体系の話ですけれども、あくまでも公の施設というのは、条例に基づいた枠内という形になりますので、そもそも指定管理者側が条例に違反するような料金設定はできない形の枠組みになっております。","voiceIndex":28,"id":"exchange-013"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いわゆる区の政策実施というのかな、企画、そういうことと、この管理者への要望というのか、期待というのか、そういうこととの折り合いというか、そういうことについて聞かせてください。","respondent":"榎本行財政改革担当課長","answer":"それ以外にも障害者のいろいろな就労支援とか、それから本課でやっている方の施策がありますので、それとの中でどういうふうに折り合っていくかという形で、課題としての事業者の認識の部分という形での表記です。","voiceIndex":30,"id":"exchange-014"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いわゆる指定管理者に期待するものがあるのはわかるんだけれども、こういう書き方をしてくると、区としてある一定の施策の部分は頼むよというふうに聞こえてならないんだよね。こういう区の施策があって、それに積極的に取り組んできてほしい。そういう要望的なものなら構わないけれども、区の施策まで移譲しちゃうみたいなところが見えるんだけど、そのように見ちゃいけないんですかね。","respondent":"新美企画部長","answer":"そういう意味でのサービスについての、利用者の状況についてモニタリング機能といいますか、日々ないしは一定の期間の中で、設置者としての区に即見えない部分も、問題意識を持って区に提案をしてもらう、提起をしてもらう、この機能は当然運営者には期待をしているわけで。","voiceIndex":32,"id":"exchange-015"},{"speaker":"林（宏）委員","kind":"質問","question":"区としてやらなきゃいけない仕事をはっきりと自覚をされていると思うけど、改めてお願いをしておきます。こういうことがいい、ああいうことがいい、こういうことを気をつけろと言えるんだけど、新たに手を挙げてくる人と、その実績を比較したら必ず新しい人は入れない。その辺をどうこれからとらえていくのか。来年も１件ある、あるいは５年という先の話で申しわけないけれども、その考え方をお願いします。","respondent":"榎本行財政改革担当課長","answer":"実績等につきましては、その施設の実績はやっていたところが有利ですけれども、類似施設をやっていた実績というのは必ずそういう事業者にもありますので、そういう中での新たな提案なり、ノウハウなりの活用というもので、今の事業者だったらその程度。","voiceIndex":34,"id":"exchange-016"},{"speaker":"林（宏）委員","kind":"意見","question":"そういう事態も、万が一の話をしているので、今そういうことを業者が起こすという意味じゃないんだけど、そういうことも想定しておかなきゃ、そのときになって慌てて、想定できる言い訳はすぐそういうのを持っていかれると、利用者が困るから、しばらく今年度いっぱいはやりますが、そういうことが想定できるんだけど、そういうことも協定を結ぶときに。","respondent":"榎本行財政改革担当課長","answer":"それは想定されるものがどういう事態によるかにもよるんですけれども、指示をして、それでもできない場合には取り消しをするというような、法的な手続としてはそのような形で想定をしております。","voiceIndex":36,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今の林委員の最後の部分にちょっと引っかかってくる、前から聞こうと思って確認したかどうかなんですけど、例えば今度協定結びまして、３月に結ぶと、当然３年後、５年後、次回の選定をする時期というのが、１年度の３月いっぱいですね、基本的な考え方として。経営者が変わったとき、これをどういうふうに考えていくのか。","respondent":"榎本行財政改革担当課長","answer":"この選定の時期ですと、５年を基本として考えますと、来年４月から始まりまして４年経過した時点、５年目に入った時点で公募の手続に入らないと手続的には、それぞれ選定期間、審査期間がありますので、５年目の管理委託が始まった春ごろには要項を出して、それから募集。","voiceIndex":38,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうなると、今言ったように、直接、区に出てこないと、指定を受けているかたはどうしたって出さないんじゃないかなというのを非常に感じるので、今、直接区の方にいろいろなメールだとか直接来ますけれども、そういうものが今までどおり管理できる体制も考えておかないと、具体的な話が入ってこないんじゃないかなというのもあるので、ちょっと２点お願いします。","respondent":"榎本行財政改革担当課長","answer":"業務の引き継ぎの部分はかなり大きな課題だろうと認識しております。実際上、今まで管理委託制度というのは業務の引き継ぎを考えないで指定をして、ずっと継続してやってきたという制度になっていますので、今回初めて期限を切った管理委託という形になってあります。","voiceIndex":40,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"ただ一番問題なのは、そこにお勤めになっていてやめていく方というのは、もう４月からここからいなくなるんだよというと、どうしてもそこら辺に影響を及ぼしてくる部分が起きると思うんですね。２年半とか４年半先の話になってくるかもしれないけれども、今からその辺を十分意識した形の締結をしておいていただきたいなというのを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":42,"id":"exchange-020"},{"speaker":"中島委員","kind":"質問・要望","question":"今の鈴木委員と同じ質問があったんですが、今の内容で少し確認できたんですけれども、やはりこういう指定管理者制度になると、これまでもなかなかこういうところの運営というものが見えない部分があって、そこで働く人たちの声などが時々届いてくるというのが現実だったわけですけれども、今度指定管理者制度ということで。","respondent":"榎本行財政改革担当課長","answer":"ただ、その年１回の義務づけだけでは当然次年度の改善計画等に活かしていかれませんので、その部分で、例えば四半期別の報告書ですとか、次年度の改善等に活かせるような形での報告書を求めるというやり方が想定されますし。","voiceIndex":43,"id":"exchange-021"},{"speaker":"中島委員","kind":"質問","question":"民間ですから、一生懸命その中でやりくりしてやっているのかなと思うんですが、そういったことが利用者にとってマイナス面が出てきてはいけないなということが１つ心配な点なんですね。区に来るのは全く氷山の一角であって、その点にはいろいろな声があるのではないかと思うんですが、こういう方たちの声がすっと通るような、反映されるような窓口みたいなものは、区としては設定されるんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"今、実際に区民の声も、その窓口へ来る区民の方、それからメール等でお寄せいただく区民の方、郵送等でいただく方、さまざまありますので、そういう今のしくみも生かしながら、実際上、どういうふうにその苦情等を集約して。","voiceIndex":45,"id":"exchange-022"},{"speaker":"中島委員","kind":"質問・要望","question":"施設によっては人がどんどんかわっていく。そこにずっと働いていない、どんどん人がかわっていくという。人間同士のふれあいというんですか。ですから、どんどん人がかわると、やはりそこに不安感というのも出てくると思いますし、その辺のところまで区はしっかり関与して見ていかなくてはいけないと思うんですが、その辺をお答えいただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"今現在やっているところが、一生懸命やって区民から喜ばれていて、それにかわるべきものがあるのかないのかという状況等を踏まえて、実際上公募するのかしないのかというのがまず大前提になりますので、その中で総合的に判断した上で、かえた方が望ましいという状態になれば。","voiceIndex":47,"id":"exchange-023"},{"speaker":"中島委員","kind":"質問・要望","question":"いずれの施設も区民のサービス向上ということが一番で、サービスを利用される方がどれだけ喜んでくれるかということが大事だと思いますので、その視点でしっかり業者を選ぶという区の資料をとっていただきたいと思いますし、またできる限りの資料というものを私たちはいただいて、その中で議会としての責任を持った判断をしていきたいと思いますので、その点でもよろしくお願いしたいと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-024"},{"speaker":"築舘委員","kind":"質問・要望","question":"今度指定管理者制度になったら、その監査をどういう形でもっと踏み込めていけるのかということ、それは議会から監査委員として２人出ているから、それはどんどん言ってくれればいいですよと言われるのかもしれないけれども、その辺のことを聞かせていただきたいと思います。","respondent":"榎本行財政改革担当課長","answer":"ただ回数等につきましては、先ほども申しましたように、今回の施設だけで６０施設ありますので、その中で効率的な監査をどのようにしていくかというのは、監査委員の方の体制等もありますので、その中で適切に対応していくというふうに思っております。","voiceIndex":50,"id":"exchange-025"},{"speaker":"築舘委員","kind":"質問・要望","question":"指定管理者制度という民間の事業者の能力やノウハウを活用するというせっかくいい試みをしようとしているわけですから、実際に内容を充実させるべく、単なる表面的なきれいごとに終わらないようにお願いしたいということを要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-026"},{"speaker":"三村委員","kind":"質問","question":"ほかの委員からもいろいろご意見出ていたんですけれども、鈴木委員ですとか中島委員と同じような問題意識を持っておりまして、３ページの事業報告書等のところで、先ほど委員会の報告書、また会議ということでお話があったかと思うんですけれども、今回出ている指定管理者の団体のところでは、人的な交流等がありまして、会議だけでも中の様子等が多分見えてくるところがあるかと思うんですけれども。","respondent":"榎本行財政改革担当課長","answer":"この評価のしくみですけれども、今現在、いろいろな検討の中では、そういう報告書等とか会議等も、区の方で行うのではなくて、その施設へ行って、実際に会議なり打ち合わせなりをするという方法も検討できますし、もしくは会議等も責任者だけの会議ではなくて。","voiceIndex":53,"id":"exchange-027"},{"speaker":"三村委員","kind":"質問","question":"そういった新しい団体が入ってきた場合、まだ先の話になるかと思うんですけれども、この選定委員会、先ほども事業部の部長、課長、あと総務ですとか企画の方が入られるということだったんですけれども、どうしても行政の場合、人事異動がありますよね。そういったあたりの評価の精度をどのように一定レベルに保っていくのか、その辺についてどのようにお考えなのかお伺いをいたします。","respondent":"榎本行財政改革担当課長","answer":"ですから、人事異動がありましても、それぞれの今までの職務経歴の中で、実際上関与している部分もありますし、関与していない部分につきましては、選定委員会の中で大いに概要等を説明を求めて議論をしていくという形になろうかと考えています。","voiceIndex":55,"id":"exchange-028"},{"speaker":"三村委員","kind":"質問・要望","question":"一から関係性をつくっていかないといけないという話とかも聞きますので、ぜひそういう情報の共有等も図っていただきたいということ、あとそうはいっても、やはり新しい人がそういう事業経験、新しく着任した方が何回かの会議で決められてしまうというところでは、事業者側からの納得というところでは、なかなか説得力というのかな、本当のこの選定方法は正しかったの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問","question":"そういった面で、コスト削減という面で、人員削減とか、賃金の問題とかがすごく大きく、職員の待遇とか処遇のところでサービスに影響してくると思うんですけれども、ここの協定の締結のところに職員配置というのがあるんですが、この辺において、例えば人件費の中身の公開がされるのかどうか、どのところまでが議会とか区民とかに情報提供できる範囲なのか、ちょっとその辺をお伺いしたいと思います。","respondent":"榎本行財政改革担当課長","answer":"情報公開というのは情報公開制度という意味なのか、それとも議会での審議の中身なのか、情報公開制度という形ですと、情報公開制度の場合には、だれに対しても同じように情報公開を行うということで、例えばライバル事業者が今後選定に入りたいということで。","voiceIndex":58,"id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、公募のところの工夫というご答弁だったんですけれども、例えば資料を出す前段階での確認というか、ここの部分はという、当然伏せていく部分はあると思うんですけれども、全く出ないような状況では判断ができないと思うので、その辺の工夫というのをもうちょっと具体的にお知らせいただきたいなと思うのと、あと情報公開制度で求められている中身の資料が。","respondent":"榎本行財政改革担当課長","answer":"１点目の工夫の部分ですけれども、プロポーザルに当たって企業ノウハウをどういうふうに説明してもらうか、そこがわからないと実際のプロポーザルの中で甲乙つけがたくなってしまうという形がありますので、その部分は逆にいくと、公募要項の中で公開していい書類と。","voiceIndex":60,"id":"exchange-031"},{"speaker":"飯沼委員","kind":"意見","question":"そういった面では、ちょっと先のことになるかと思うんですけれども、今回の品川区のような個別の条例の中に手続を入れていくというのではなくて、包括的な手続条例をきちんとつくって、その中に、例えば一番チェックしたいのは情報公開のところなんですけれども、両方にきちんと明記をしながら公開をさせていくというぐらいの歯どめがないといけないんじゃないかと思っているんですが、これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":62,"id":"exchange-032"},{"speaker":"武内委員","kind":"質問","question":"２点あるんですが、１つは、指定管理者の選定の委員会で選定する前に、もしくはその場にいろいろな、今回は競合がなかったということなんですが、いろいろな資料等、事業計画書等がありますけど、その場に、もしくはその前に、その指定管理者の、例えばきゅりあんで言えば文化振興事業団の方の責任者もしくは代表の方とお話し合いというか、プレゼンテーションというんですか、意気込みというか。","respondent":"榎本行財政改革担当課長","answer":"今回、選定委員会の中でそういうプレゼンテーションを受けたのは、区営住宅、区民住宅の管理者は民間事業者ですので、その３者についてはそういうプレゼンテーションというのを行った上で選定の審査に入ったという形です。","voiceIndex":63,"id":"exchange-033"},{"speaker":"武内委員","kind":"提案","question":"そうすると、ほかのところは今までの実績とか、そうしたものを常時見ていらっしゃって、また常時いろいろなことのやりとりをされているからということでやられなかったんじゃないかと思うんですけれども、そうした中で、今回、私も区民委員会で、きゅりあんに関して指定するかどうかという議論をさせていただいたんですけれども、その中で、指定管理者になるからということではないと思うんですけど。","respondent":"榎本行財政改革担当課長","answer":"その他につきましては、細かいところはありますけれども、大きな枠組みとしては、そのような変更というのはなかったと記憶しております。","voiceIndex":65,"id":"exchange-034"},{"speaker":"武内委員","kind":"質問・要望","question":"次回の５年後、３年後のときには、新しいところも入ってくると思うんですけれども、今まで継続してやられていたところも、できれば新たな意味でそういった新たに指定管理者候補者という形で公募されてきた中であれば、そうした意欲ですとか取り組みに対してのそういうものを聞く場をぜひ設けていただきたいという要望と、あとスケジュール的なところで先ほどありましたけれども。","respondent":"榎本行財政改革担当課長","answer":"公募する場合につきましては、まず公募要項を発表する前の段階で議会等に報告をして、これからこういう事業者、こういう施設に対して公募を行いますという報告をした上で、それぞれ手続に入っていきたいと考えております。","voiceIndex":67,"id":"exchange-035"},{"speaker":"武内委員","kind":"意見","question":"わかりました。それで、例えば締め切りがいつですよと。それでその応募状況ですね。それをどういう形でお知らせするのか、時期的なものも含めて。","respondent":"榎本行財政改革担当課長","answer":"その後、応募を締め切って選定委員会をやって、指定議決にいくまでにまだ時間がかかりますので、その中で最終的には指定議決のときに説明等はしますけれども、随時その途中経過でのお知らせというのはするようにしていきたいと考えております。","voiceIndex":69,"id":"exchange-036"},{"speaker":"武内委員","kind":"質問・要望","question":"いろいろな状況によって、できないことはないと思うんですけれども、そうしていただいた方が、先ほどありましたけれども、いきなり第４定例会のときに出てきて、今、資料が少ないとか多いとかありましたけど、かなりの資料がそこの場でもし出たときに、正直言ってその場でその資料を精査して決めるというのはちょっと無理だなと考えていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":71,"id":"exchange-037"},{"speaker":"沢田委員","kind":"質問","question":"私は議会で議決をするに当たってどういう審査をすべきかという点で先ほども質問したんですけど、改めて、今度の指定管理者を議会で議決する前、区が候補者を選定する段階で、どんな資料を提出させているのか、主立ったものと、それから選出過程で作成される文書はどんなものがあるのか、説明願いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"最初の方なんですけれども、どんな資料というのは、実際に選定に入る前にということでしょうか。実際上、今回、指定管理者のいろいろな手続の一番最初のスタート地点というのは、基本方針の策定という段階が、区としての方針決定という形で手続的にはスタートしています。","voiceIndex":72,"id":"exchange-038"},{"speaker":"沢田委員","kind":"質問","question":"このうち議会に示すべき資料は何と何なんでしょうか。それから、先ほど飯沼委員から議事録の問題が出されて、概要だけれども議事録はつくっておりますという話だったんですが、これは議会に資料として提出していただけるんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"議事録につきましては議事要旨という形でまとめておりますけれども、それは議会側からの要望等があれば出すという形は可能と考えております。","voiceIndex":74,"id":"exchange-039"},{"speaker":"沢田委員","kind":"質問・要望","question":"だけど、少なくとも住民サービスが低下したり、何か問題ある企業、ＮＰＯ団体を選定しない最低限の審査はすべきだと思うんです。それから、私はもっと議決をするんだから極力出すべきだ。私はもっとつまびらかに議会に、もちろん出していい資料、出していけない資料があることは否定しませんけれども、もっとオープンに議会を信用して出していただきたいということだけ述べて終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":76,"id":"exchange-040"},{"speaker":"大西委員","kind":"確認","question":"ちょっと基本的なことと、それと少しかけ離れたことになるかもわかりませんけれども、昨今、建築確認等でいろいろな問題が起こっているということをご承知だと思うんですけれども、これに関しては民間が建築確認をおろしていろいろな問題が発生してきているということですけれども、この指定管理者制度をとって、もし問題が発生した場合の責任の帰属ということについては、どのような認識でおられるのか。","respondent":"榎本行財政改革担当課長","answer":"この公の施設の設置者である区が責任を負うという形になります。要はあくまでも設置をしたのは区で、政策目的をもってその事業を執行しておりますので、その執行がうまくいくのかいかないのかという部分の責任というのは区が負うという形になります。","voiceIndex":77,"id":"exchange-041"},{"speaker":"大西委員","kind":"質問","question":"その部分に関しては、およそ事業部等でヒアリングを行っていることだと思うんですけれども、このヒアリングの内容を区が掌握しているわけですから、区がその部分を公開できる、できない等、先ほどの中では区が掌握したものに関しては公開が前提であるということでしたが、例えばもし企業のノウハウであるから公表できないという議論があるとすると、この部分に関してはどうですか。","respondent":"榎本行財政改革担当課長","answer":"この選定委員会の審議に関しましては、基本方針の中で審議は非公開という形をしておりまして、実際上その内容等は議事録等で書かれている部分と書かれていない部分というのはあるかもしれませんけれども、審議そのものは非公開で行っているということで、非公開でないと。","voiceIndex":79,"id":"exchange-042"},{"speaker":"大西委員","kind":"質問","question":"私どもがこれを議決するに当たっては、その会社が本当にそれだけのノウハウを持っているかどうかをよく承知できず議決をするということになるんじゃないかなと思うんですね。私はそういう点で、およそ１年間、２年間、３年間とやっていけば、いずれそのノウハウを出してやるわけですから、それがその場で非公開であって何か意味があるのかなと。それを非公開することに意味があるのかなと思うんですが。","respondent":"榎本行財政改革担当課長","answer":"審議のヒアリングの部分というのは非公開という扱いですけれども、この表現等につきましては、今後の選定理由の表現方法は限られた字数の中でどう表現するかという形になりますので、抽象的になりますけれども、その具体的な部分につきましては。","voiceIndex":81,"id":"exchange-043"},{"speaker":"大西委員","kind":"質問・要望","question":"先ほどの中で責任が区に帰属するですので、もう少し私どもが議決するに関しましては、中身がより理解できるような資料の提出を今後望みます。これは要望としてお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-044"},{"speaker":"三村委員","kind":"提案","question":"なるべく提案内容と指定管理者のその後のノウハウということで違うと思うんですけれども、提案内容をどこまで出すかというだけじゃなくて、その後のすぐれた事業内容をなるべく区内で共有できる、同じようなレベルを維持できるような、共有化できるようなそういった考え方も必要かと思うんですけれども、その辺についてお考えがあればお聞かせ願いたいと思います。","respondent":"榎本行財政改革担当課長","answer":"事業でのすぐれたノウハウというものは、それぞれの事業者間もしくは行政との間での共有というのは十分可能だと思いますけれども、その中で民間事業者がそのすぐれたノウハウがなければ選んでもらえないというのも一方でありますし、ＮＰＯ等に比べましては。","voiceIndex":84,"id":"exchange-045"},{"speaker":"林（宏）委員","kind":"提案","question":"６０施設が示されているわけですけど、残りの指定管理者制度導入の事業について、９月まであるわけですから、来年の第２定例会までに出してくる予定数、なぎさ会館とか臨海斎場は５区でやっているんだけど、品川区が提案して５区でこういう制度というのも可能性としてはあるわけで、その辺の、現在、区側としてわかっている範囲、幾つぐらいやる予定とか。","respondent":"榎本行財政改革担当課長","answer":"今後指定管理者制度導入をする施設の予定ですけれども、１つは新規導入ということで、都南病院跡地の高齢者福祉施設については公募型プロポーザルという形、それからあと想定として挙げておりますのが品川と荏原の健康センター。","voiceIndex":86,"id":"exchange-046"},{"speaker":"林（宏）委員","kind":"意見","question":"これは僕の個人的な持論なので、議会全体がどういうふうにというのはわかりませんけれども、行政がする行政評価、政策評価というのは、あくまでも行政の立場に立ってしていくものです。その評価を評価してもあまり意味がない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-047"}]},{"id":"topic-02","title":"議員定数に関すること","agenda":"議員定数に関すること","exchanges":[{"speaker":"中島委員","kind":"質問・要望","question":"それとともに、全国的にどういう状況なのかなというところも調査させていただきました。そうした方たちがいろいろ区政に対しての要望なんかも届けてくださる、こういうことも現実にあります。そこは品川と比べてどのぐらいの差があるのかなと、それが一概にこの標準になるかどうかわかりませんが、議員割で計算したところ、葛飾の場合は議員４０名として、１人当たり１万９７４人なんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":99,"id":"exchange-048"},{"speaker":"大西委員","kind":"意見","question":"私どもでは、例えば人口が増えてきているという点からしますと、港区、渋谷区等を見ますと、港区については条例定数３４名で現状も３４名である。そして品川区に一番近いといいますか、人口で言えば、今年度１１月１日現在、中野区で２９万７,０００人、今、品川区は３３万７,０００人だと思いますが、中野では現在４２名の定数である。２９万人でその状態ですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":101,"id":"exchange-049"},{"speaker":"沢田委員","kind":"提案","question":"３番目は、議員はそのようなチェック機能だけじゃなくて、住民の立場でおれならこうやる、我が会派ならこうやるという要望を、条例案あるいは予算修正案という格好で、立法機能を生かすべきだというのは、この間２回の行財政改革特別委員会の講師を招いてやった中でも共通して、今のままでチェック機関だけであってはならないということを講師の方が言われたように、各党がある意味では競い合って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":103,"id":"exchange-050"},{"speaker":"築舘委員","kind":"質問","question":"ですから、現状維持ということになりますと、どうしても議員としてはこれでいいのかという状況でおさまってしまいがちですので、常に改革ということを旗印に、行財政改革はもちろんのこと、行政の人たちは常に職場においても、人数のことに関しても、退職不補充ということで減らしていくという努力をしているわけです。それによってサービスは減らさないように、区民サービスは徹底的にやると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-051"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"数字については２つ案があって、今回どちらを提示するべきか今迷っています。それから減としたら、減の今、２つの数字が出てきましたけれども、どちらの数字で減というのを進めていくのか、減は賛成だけど、数字では相いれないという意見になるわけですから、その辺の整理をこの行財政改革特別委員会の進め方、それから議会全体というか、どういうところで最終的な結論を得るというふうに持っていく。","respondent":"須藤委員長","answer":"一通りご意見をいただきましてから、進め方については対応していきたいと思います。続きまして無所属の会。","voiceIndex":107,"id":"exchange-052"},{"speaker":"三村委員","kind":"意見","question":"そういったところでは、人数が減っていくということは議員の多様性が失われていくことにもつながりますので、どうやって民意を反映できるシステムをつくっていくのか、議会としても住民にとって開かれた議会、また住民参加のしやすい議会、今回傍聴の方がたくさんいらっしゃっていますけれども、傍聴の方に資料も配布していないというような状況ではなくて、住民参加。","respondent":"須藤委員長","answer":"それぞれご意見をいただきました。今、林委員から今後の進め方について１つの方向性を出さなければ、次に進めないんじゃないかというお話をいただきました。委員会のあり方、進め方についてご意見等がございましたら、ご発言を願いたいと思います。","voiceIndex":111,"id":"exchange-053"},{"speaker":"藤田委員","kind":"意見","question":"今、数字の件で２つに分かれていたり、削減をするという会派もございました。１になるのか、２になるのか、３になるのか、４になるのか、これはわかりませんけれども、そういう諮り方でお願いできないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":113,"id":"exchange-054"},{"speaker":"林（宏）委員","kind":"提案","question":"ですから、そういうことも含めて、今日から１２月ですけど、１、２、３、４と我々の任期の行財政改革特別委員会というのがあるわけですから、その４カ月、５カ月の間にどの手順を踏んで、どういうところに私たちの意見を上げていくかというのをきちんと諮っていってやらないと、１回ずつ、じゃあ今日はこれをやりますよ、こういうことをやりましょうという時期ではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":114,"id":"exchange-055"},{"speaker":"沢田委員","kind":"提案","question":"私どもは現状で最低限いくべきだという意見なんですが、最終的には委員会の提案にはならないですよね。賛同する議員が議案提案をやるという格好になるわけで、先ほど意見表明した段階では４会派対３会派かな。なぜ削減を、２あるいは４を提案をしたのかということについて聞きたいんですが、いかがでしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":116,"id":"exchange-056"},{"speaker":"藤田委員","kind":"質問","question":"私はその中で言っていることは十分だと思うんですけれども。したがって、先ほども申し上げましたけれども、次の選挙のどれぐらい前にこの結論というのをつけるかというのを逆算して考えますと、１年前には、それぞれ次に立候補したいという方もいらっしゃるわけですから、少なくとも今年度以内で一定の結論をつけてあげた方が、私は親切ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":118,"id":"exchange-057"},{"speaker":"大西委員","kind":"意見","question":"そうなると、果たしてこの議会自体が本当に区民の代弁者の状況なのか、そうじゃない１つの支持団体の人たちの非常に有利な場になってしまうという危惧も議員定数削減にははらんでいると思いますので、これは軽々に議員定数削減ということのみで話していくことには、私は強い危機感を覚えるところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":119,"id":"exchange-058"},{"speaker":"沢田委員","kind":"意見","question":"１年半後に区議選を控えて、非常に微妙な問題を今、論議しているわけですけれども、前回もそうでしたけれども、議員定数を削減するときに、全員協議会を開いて全体の意見交換をしているんですね。大変申しわけないんだけど。それから活性化するという、議員定数を削減するとどこがどう活性化するのかというのもどうももうひとつよくわからないし、他区がやっているからうちもって、そんな軽々な話はないでよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":121,"id":"exchange-059"},{"speaker":"沢田委員","kind":"意見","question":"私は注意して言ったつもりなんですけど、前段の助走部分ではかなりやってきた。だけど、具体的に増か減か、何のために増減をするのかということを各党が表明したのは前回だから、いわゆる核心に入ったのは２回という意味で、その前にずっと調査してきたということまで否定してはおりませんので、ご理解をお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":123,"id":"exchange-060"},{"speaker":"中島委員","kind":"質問・要望","question":"じゃ、そこの問題が起きたようなところの行政は、果たして議員の定数はどうなんでしょうかということも知りたいなという疑問があります。住民の声が反映されているのか。じゃあ、住民の方のお声の中には、今、現状の議員がすべて１００％住民の声をきちんと反映している議員なのかどうか、こういった質問もありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":124,"id":"exchange-061"},{"speaker":"沢田委員","kind":"確認","question":"イーホームズの建築確認審査機関のチェック機関と言ったのは、そこの議会がどうこうという意味で言ったんじゃなくて、民間の確認検査機関そのもののチェック機能が働かなかったという意味で私は言ったので、そこの議会がということで言っているわけではありません。１億６６６万円出ているのにね。むしろ住民の声にこたえて、しかるべき議会の任務を果たすそのときが今ではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":125,"id":"exchange-062"},{"speaker":"武内委員","kind":"質問","question":"葛飾区に問いあわせて葛飾の区議会議員にお聞きした際には、なぜこんなに一気に減ったんですかというお話を聞いたんですね。５６の定数の法定定数に対して４６の条例定数になっているんですね。割返すと０.８２１だと。これを葛飾に当てはめると葛飾の法定定数が４６ですから、それにこれを掛けるとどうなるか。実は３８だと。それに対してどうかという議論の中で６名という話が出たんだよと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":126,"id":"exchange-063"},{"speaker":"築舘委員","kind":"質問","question":"ただし、それを何人にするかといったときに、急激に人数を減らす場合には、これはいろいろ差し障りも出てくる。要するに質の向上ということだけを目指して、数を極端に減らすことによって質の向上はどうなるんだという議論もあるわけですから、ただ単に減らせばいい、多く減らせばいいということではない。","respondent":"須藤委員長","answer":"先ほど林委員から全員協議会で、この委員会で決めることの考え方ということで示されましたけれども、私の方では、先ほど言ったように、議員定数に関することは議会運営委員会でこの特別委員会をつくられて１つのテーマになったので。","voiceIndex":127,"id":"exchange-064"},{"speaker":"林（宏）委員","kind":"提案","question":"だから、もし議長に対しての委員会としては削減すべきという結論ですという提案を持ってこの委員会の結論とするのか、例えば委員会として２名の削減の改正する条例をつくって、議長あてにこういう提案をしていきたいとやるのか、そういうところをもう少し煮詰めないと、さっき沢田委員なんかはそういうところじゃないだろうと、報告をすればいいんだろうという考え方。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":129,"id":"exchange-065"},{"speaker":"沢田委員","kind":"意見","question":"討論はそれぞれ会派の政治であっても、こういう点があるからこの案件に賛成してほしい、反対してほしいという、そういう意味で討論という制度があるわけで、確かにそんなに簡単に変わるほどのものだと私はもちろん思っておりませんけれども、やっぱりそこは議論を尽くすという点で、自分らの会派の主張だけじゃなくて、他会派の意見にも耳を傾けたいと思っていますよ、正直言って。むしろそこは聞きたいと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":131,"id":"exchange-066"},{"speaker":"沢田委員","kind":"提案","question":"たしか鎌田前議員だと思うんですけれども、条例提案でそのことを言ったんですね。それをやったのが１９９４年なんです。それはいろいろ言われましたよ。だけど区民の要望は議会は議会らしく本来の任務を果たしてくれ、それから海外調査みたいなものはやめてくれということが多数なのであって、ここは削減した方がいいといってどんどん減らしていったら、議会制民主主義は根底から瓦解すると思いますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":133,"id":"exchange-067"},{"speaker":"林（宏）委員","kind":"質問","question":"この点は沢田委員と同じ。結論を持っちゃってからやってもそう意味はないと思うので、最終的に私たちが、最後の形がどうなるにしても、この委員会の中でいろいろな形でまとめなきゃならない。その最終的な自分たちの意見を出すところの参考にしていきたいということですから、例えばここでこの委員会は削減の方向を決めます。例えば決をとるとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":135,"id":"exchange-068"},{"speaker":"大西委員","kind":"意見","question":"先ほどありましたけれども、減らすには減らすだけの理由として、例えば人口が大幅に減ってきたから減らすんだと、だから減として私たちはどうこうするということに至っていなくて、現実的には議員定数を１つも減らしていない区もたくさんある。例えば中央区では８万９,０００人で３０人の議員がいる。私たちは既に４６名から４２名という形で汗を流しているんです、血を流しているんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":136,"id":"exchange-069"},{"speaker":"大西委員","kind":"質問","question":"今、現状で法定定数が私どもは４６名なんですよ。そこから今は４２名まで減らしているんです。皆さんの中で合意がなされていない中で、議員定数が本当に必要かどうかというのが、私はよく大井町の駅頭に朝立って演説をしているときに、いろいろな方々から言われますよ。この点はどうなんだ、あの点はどうなんだ、私はこう思うんだと。あなたはどこにお住まいなんですか。ほかの議員に尋ねたんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":138,"id":"exchange-070"},{"speaker":"中島委員","kind":"意見","question":"ちょっと一言申し述べておきたいんですが、今、大西委員の方から公明党は行革のためだけにというような評価がありました。それともう１点、街頭演説をやっているだけが議員の仕事ではないと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":141,"id":"exchange-071"},{"speaker":"飯沼委員","kind":"提案","question":"そういった面で、私は前回、区民にとって議会がどう映っているのか、その辺の議会と民意とのコミュニケーションというか、そういうところで今どういう状況なのかなと思って、この間、投票率の話もしましたけれども、半分以下の投票率が続いている中で、私なんかは地域でいろいろご意見を聞く中で、自分たちの声をどこに出したらいいのかとか、出しても変わらないんじゃないかというあきらめの部分。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":142,"id":"exchange-072"},{"speaker":"三村委員","kind":"質問・要望","question":"今回のこちらの行財政改革特別委員会というところでは、特定事件調査ということで、議員定数ということであらかじめ枠が設けられているものがありますので、議員定数以外の部分について絡んだ深い議論というのは、それはここの委員会ではありませんよというところでなかなか議論を出しにくい部分がありましたので、もちろん議員定数をメインにということで構わないかと思いますけれども、議員定数も含めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":143,"id":"exchange-073"},{"speaker":"武内委員","kind":"質問・要望","question":"結論の出し方は別として、そういうことは皆さんと同じご意見だと思いますので、そうした中で時間的に見ますと、あまり議論の窓口を広げるよりは、今日結論云々ということじゃなくて、今日は人数ということだけお聞きしていますので、今日いきなり結論というとまたそれぞれ意見があると思うんですけど、どこかの段階でそういう方向性を確認できる結論をとるべきだと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-074"},{"speaker":"沢田委員","kind":"提案","question":"私はそういう協議会を開いて全議員に意見を聞く場は最低限やるべきだと思います。そうじゃないですよね。今おっしゃられた、全員協議会までに減とかどうとかと決めておかないで、とりあえずやろうという提案は私は賛成ですので、ぜひそういう方向で、むしろ全員協議会を開くなら、いつ開くのかということの方に、開く開かないというのはまだ決めておりませんけれども、した方がいいんじゃないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":145,"id":"exchange-075"},{"speaker":"藤田委員","kind":"質問・要望","question":"全員協議会の役割については十分認識をしておりますけれども、当委員会で定数に関していいのかどうかというその議論を課せられて、今日までさまざまな形で知恵を出してもらい、大学の先生にも２回ほど来てもらい、３回ですか、１回かな。地域の行事も入ってくるでしょう。これは私の要望ですけどね。ですから、これは結論的には正副委員長で話し合って、どういうふうに結論するのかわかりません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-076"},{"speaker":"大西委員","kind":"質問","question":"３点ほどあるんですけれども、先ほど中島委員が言われた、私は別に演説をやっている人が議員の代表と言っているんじゃなしに、私に尋ねてきている人たちに、あなたが相談する近くにもっと議員がいないんですかということを申し上げたので、演説している人がいないんですかということを申し上げたんじゃないので、ちょっとその解釈をしっかりしてほしいのと、それと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":147,"id":"exchange-077"},{"speaker":"中島委員","kind":"質問・要望","question":"今の発言の中で１つ、特定の支持団体を抱えているとか、そういう表現というのは私は間違っていると思います。何でこれまでやってこなかったんですかと言いたいと思います。現実には３年前からこの問題は提起されているわけですから、それぞれ会派として、また個人として考えてきたことではないかなと信じておりまして、その上での発言をしていますので、その辺のところをご了承いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":148,"id":"exchange-078"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"大分流れがつくられてきたと思うんですけど、最初に言ったように、ほかの特別委員会でやっているように、議長あてにこの委員会のまとめというか、結論を報告するようにするのか、あるいはもし減というのが出たときに、よく沢田さんが言う立法府の役割を果たせという意味からすれば、そういう方向もこの委員会でとっていくのか、そういうのも一回議論した方が、今日ということじゃなくてね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":152,"id":"exchange-079"},{"speaker":"須藤委員長","kind":"提案","question":"委員長としては、今言ったように、必要なことは、もし削減するということであれば、どの定例会で条例提案してくるか。ほかにご発言ございませんでしょうか。本日の予定は終了いたしましたので、行財政改革特別委員会を終了といたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":153,"id":"exchange-080"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5790#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":62866,"voices":153}},{"id":"h17-20051206-16","meetingId":"h17-cm12","date":"2005年12月6日","dateIso":"2005-12-06","committee":"街づくり特別委員会","time":"午後１時１８分～午後１時５８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"公有地の活用（日野中学校跡地）のまとめ","agenda":"公有地の活用（日野中学校跡地）のまとめ","exchanges":[{"speaker":"山村委員","kind":"意見","question":"前文を見ますと、日野中学校跡地のことだけが書かれていますので、２番とのつながりが薄いと思うんです。この文章だけ読むと、第一日野小学校跡地のことが、急に２番で出てくるような感じがしますので、何かしら文章に入れられたほうがいいかなと思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":4,"id":"exchange-001"},{"speaker":"山村委員","kind":"質問","question":"そこでまとめについても、日野中学校跡地および第一日野小学校跡地を、ここの表現がちょっと見つからないんですけれども、一緒にまとめとして出すとか、そういう感じで、何かしら入れられたほうが、小学校跡地に関しては、前文に全然かかわりが載ってないので、小学校跡地も、日野中学校跡地と同じようにずっと議論をしてきたわけですから、そのことを載せられたほうがいいんじゃないかなと、私は思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":6,"id":"exchange-002"},{"speaker":"中塚委員","kind":"提案","question":"今の山村委員のご提案ですけれども、例えば、「９月２８日の当委員会において、日野中学校跡地の利用計画案が示された」と、ここで言われている日野中学校跡地利用計画案というのが、いわゆる第一日野小学校を日野中学校に持っていくことと、第一日野小学校跡地のことが含まれているんですけれども、たしかにここで、利用計画案だけを読むと、わからないというのは一理あるかなとは思うんです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":8,"id":"exchange-003"},{"speaker":"本多委員","kind":"意見","question":"まとめということなんですけれども、１番、２番と分かれているんですけれども、１番目のことは、日野中学校跡地に第一日野小学校が移ることについての意見ということで、この三つは、おおむね委員会としての意見でいいと思うんですが、前回、うちの会派が出した中に、開校した後の学校の運営について、地域の拠点としてのことをもとに運営をしてほしいという趣旨の意見を１番に持っていったわけですので。","respondent":"宮崎委員長","answer":"今の２番目のほうの意見については、確かにおっしゃるとおりなんですよね。","voiceIndex":10,"id":"exchange-004"},{"speaker":"本多委員","kind":"意見","question":"１番目のほうの、さっき言った趣旨というのは、学校の使われた方とか、よく開かれた学校とか言われる意味で、学校が教育現場として使われるのは、もちろん何よりも優先されなければいけませんが、それ以降、地域でも活用するとか、例えば土曜日とか、日曜日のグラウンドのつかい方とか、そういう細かいことも含めて、地域拠点ということを盛り込む。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢委員","kind":"提案","question":"今の本多委員の意見に補足なんですけれども、地域の防災拠点ということの意味合いからすると、地域のコミュニティの拠点として、機能の充実を図っていただけば、防災も含まれるでしょうし、いろいろな防災以外の地域の活動も含まれると考えますので、文言の整理をしていただくことがどうかということで、文言の変更という部分で、「防災拠点」ではなくて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-006"},{"speaker":"三上副委員長","kind":"質問","question":"現実に、そこはもう地域の拠点という形で提供されているということになれば、あえてそこにもそういった項目をつける必要があるのか、どうかと、私はちょっと受けとめるんです。五反田文化センターについては相当古くなってきているわけですから、将来的には建て直しも十分に考えられる。となれば、あえて屋上屋を重ねるような施設にというところまでは考えなくてもいいんじゃないかと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問・要望","question":"その後、そういう背景があったので、委員会として、「緊急かつ効率的な取り組みが強く求められました」と。この時期にまとめて、予算に反映されたいという当委員会の思いもありますので、そこの部分を、少しわかりやすく具体化されればいいかなと思いました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"「９月２８日の当委員会において、日野中学校跡地の利用計画案が示された」とありますが、この利用計画案というのは、この間、お話ししたように、１、２、３ということで、３番目の項目で、第一日野小学校の跡地が出てきているわけですから、それが別の項目で出ていれば、やはり書いてあれしなければいけないと思うんですけれども、大きな項目の、利用計画案のうち、１、２、３項目の部分的な項目なので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"それとはまた別の話題なんですけれども、さっきちょっと触れたんですけれども、「緊急かつ効率的な取り組みが強く求められました」というところで、これは文言を変えるわけじゃなくて、僕の意見なんですけれども、この間、跡地利用に関していろいろ話を聞いておりまして、去年３月ぐらいからＴＯＣとの話がある中で、議会に対しては、特別委員会を開いて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-010"},{"speaker":"西本委員","kind":"意見","question":"１番目、２番目という形で、議論の流れが書いてありますので、まずは移転ということに対して、それはそれで、皆さんの合意が得られた。第一日野小学校移転後の跡地活用については、さらにいろいろ議論があったと。ただ、それについては、今後、長い期間もありますので、いろいろ意見がありましたというような形になっていると思いますので、私は、このままでよろしいのではないかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":20,"id":"exchange-011"},{"speaker":"本間委員","kind":"提案","question":"前文の部分、先ほど、山村委員のほうからも話がありました。私どもも、実は、前文を読んでいますと、一言も第一日野小学校という部分が出てこないわけです。そうしないと、何かちょっとつながりが出てこないし、出された提案は、日野中学校と同時に、第一日野小学校跡地の部分が絡んでいるわけですから、一応、前段の部分に一言も触れていないというのは、そういうような方法があるのではないかと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":21,"id":"exchange-012"},{"speaker":"南委員","kind":"質問・要望","question":"委員会運営としては、いろいろな場面がありますから、こういうところがあることは、それはやむを得ないと受けとめていかなきゃいけないと思いますけれども、今回の区と議会と同じ歩調で進んでいかなかったという状況というのは、やっぱりできるだけ押さえていかなきゃいけないと思いますので、できるだけ速やかな情報提供も含めて、これからやっていかなきゃいけないという改善の思いも込めて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":22,"id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"先ほどほかの委員からありましたけれども、中断の７行目ですか、「日野中学校跡地」に、また「と第一日野小学校跡地を含む」とすることは大切なことなのかなと。というのは、公有地活用に関することということで議論をしてきたわけで、日野中学校の跡地に学校を建てるということに関してですから、これに関しては、そんなに問題にもならないのかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-014"},{"speaker":"西本委員","kind":"提案","question":"やっぱり日野中学校の跡地については、視察も行いましたし、皆さん議論をする時間を設けているわけですから、それでも十分に話をしたと考えています。理事者のほうから提案されていたのは、日野中学校への第一日野小学校の移転と、その第一日野小学校の活用ということが一緒に出てきているわけですから、それが利用計画案という形で出ているので、分離した形で出てきていないと思います。","respondent":"宮崎委員長","answer":"原案でいいというご意見もありましたけれども、皆さんからいろいろご意見をいただきましたので、それをちょっと今、正副委員長で扱いを検討させていただきました。その結果、正副委員長のところでは、案として、二つお示ししたいと思います。","voiceIndex":25,"id":"exchange-015"},{"speaker":"大沢委員","kind":"質問","question":"案として、もうまとまっているわけですよね。ということは、案として策定をされているわけですよね。それで、２８日の委員会に出てきているわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"基本的にいいと思います。先ほど、委員長が、正副委員長で打ち合わせされて提起してくださったところに、私の意見が入っていなかったので、改めてちょっと。全員の一致になっていないから、それはそれでしようがないと思っていますけれども、改めてそういう思いというのは、行政のほうとしても受けとめて、今後に生かしていただきたいということを、ちょっと強くお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6316#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":8769,"voices":33}},{"id":"h17-20051208-9","meetingId":"h17-cm12","date":"2005年12月8日","dateIso":"2005-12-08","committee":"文教委員会","time":"午後２時１３分～午後２時２９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を7件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","agenda":"第１０７号議案、幼稚園教育職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今の説明を伺って、民間との較差が０.９７％あるので是正するということなんですが、るる扶養手当とか、勤勉手当の改正の内容の説明をいただいたんですが、０.９７％というのは、全体を通じてオーバーしているという考え方なんでしょうか。それから、民間との較差が生じたという、その民間というのは、どういうことを概念として持てばいいのか、教えていただきたい。","respondent":"市川庶務課長","answer":"今、説明申し上げたように、例月給については、公務員給与のほうが上回っている、ボーナスについては民間のほうが上回っているということで、片や引下げ、片や引上げという改定内容になってあります。２番目のご質問です。","voiceIndex":5,"id":"exchange-001"},{"speaker":"南委員","kind":"質問","question":"そういう体系というのは、今は全くなくなって、いわゆる民間というのは、１００人以上、５０人以上それぞれなんですけれども、１００人以上ですから、当然大企業も入っているんだろうと思うんですけれども、いわゆる大企業とか、中小企業、そういう小さな事業所も含めたトータルのサンプリングということなんですか。","respondent":"市川庶務課長","answer":"人事委員会勧告のもともとの根拠は、地方公務員法に定められてございまして、いわゆる公務員の給与は民間準拠という原則を打ち立てる中、民間事業の従事者の給与ということが、はっきり法文の中にうたわれてございまして、その意味で、公務員の給与を徹底する際に。","voiceIndex":7,"id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"これは、そういう制度の中で行われているところの条例改正ですから、それはそれでやむを得ないということは承知しながら発言するんですけれども、景気の回復を、この問題だけではなくて、きちんとした必要なときに、必要な角度での発言というか、姿勢をしっかり向けていくということが、改めて大事なのかということを、ちょっと強く感じております。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"沢田委員","kind":"質問","question":"ここの労働条件や賃金なんていうのは、比較にならないほどひどい状況で、別に右へ倣えしろ、入れろということで言っているんじゃないですよ、事実関係として、労働市場が流動化しているその問題については、ある程度考慮された上での調査なのか、そこら辺はどうでしょうか。旧態依然とした正社員としてのあれだけなのか、ちょっとわかったら教えてほしいんです。","respondent":"市川庶務課長","answer":"冒頭申し上げたように、どういう分野の業種を調査対象にしているかということについては、今の日本の経済情勢、産業界の動向を極力反映できるような平準化した業種の選定を行っているという説明を受けてあります。","voiceIndex":10,"id":"exchange-004"},{"speaker":"沢田委員","kind":"意見","question":"これは意見なんですけれども、先日、ある新聞で読んだんですけれども、北海道から新卒の高校生が就職するときに、派遣労働か請負しかない。学校で一生懸命勉強したのが、まともに将来の生活設計できないような労働状態というのは、とりわけ若い人たちの間に広がったんです。フランスなんかでは、非常勤の職員、いわゆるパートの人たちを、正社員より１５％高く雇わなきゃならないと法律で決めている。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":12,"id":"exchange-005"},{"speaker":"大沢副委員長","kind":"質問","question":"人事委員会で、官民較差を是正するということで、こういう議案が出てきたわけですけれども、比較をするときに、私立幼稚園との比較はされているんでしょうか。私立幼稚園の先生方の給与体系と、こちらのほうとの比較はされているんでしょうか。","respondent":"市川庶務課長","answer":"一方で、幼稚園の教育職員の給料表の勧告に当たりましては、東京都の人事委員会勧告が出しています小・中学校の教職員に関して、特に小学校教員の給料表に準じたものとして、特別区の幼稚園教育職員の給料表の改定を行ってありますので、当然。","voiceIndex":13,"id":"exchange-006"},{"speaker":"大沢副委員長","kind":"質問","question":"幼稚園教育職員の給与に関する条例の一部を改正する条例なんですが、では、ちょっと整理をしますと、幼稚園教育職員の給与に関しては、官と民、いわゆる私立と区立では比較は不明ということで理解していいですか。","respondent":"市川庶務課長","answer":"ある特定の業種、私立幼稚園と比較をして、それを個別に反映させるということはやってございません。そのことだけはご理解いただければと思います。","voiceIndex":15,"id":"exchange-007"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4558#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":5658,"voices":21}},{"id":"h17-20051208-5","meetingId":"h17-cm12","date":"2005年12月8日","dateIso":"2005-12-08","committee":"総務委員会","time":"午後２時０９分～午後２時２０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を3件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"第１０６号議案、職員の給与に関する条例の一部を改正する条例","agenda":"第１０６号議案、職員の給与に関する条例の一部を改正する条例","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"一つは、職員団体との関係をお伺いしたい。それから、今、年間平均４万８,０００円の減ということで、非常に大きいなという感想を持ちました。それから、４万８,０００円と言われましたけれども、それぞれの額がわかったら、お伺いしたいと思います。","respondent":"桑村人事課長","answer":"一つは、職員団体との関係ですけれども、１１月２１日に職員団体と交渉して、回答をしているものです。それから、給料表につきましては、行政職から医療職三まですけれども、基本的に同じ考え方です。ただ、いわゆる年齢層の若い者については、減額が少ないというものです。","voiceIndex":5,"id":"exchange-001"},{"speaker":"宮崎委員","kind":"質問","question":"今の説明ですと、年齢が高くなれば高い額になるということなんですけれども、私も、民間で働いていたときには、給料表をどうするのかというのをいろいろやってきた中で、非常に苦労したのは、実際に子育て世代の場合に、教育費だとかが非常にかかる。そういう年代をどうするかと。このままいっていいのかと、私は常に思うんですけれども、そこら辺のところは、どういうふうにお考えでしょうか。","respondent":"桑村人事課長","answer":"いずれにしても、公務員制度そのものが、いわゆる給料決定そのものが、どうして決められないといいますか、そういう考えがあるかと思います。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"確認","question":"先ほど、各課長、部長の金額は、前回、委員会にご報告いただいた分だと思うんですけれども、その報告の中の数字が、改定前は７１６万５,０００円という金額が出ていた中で、つい最近、１日付の広報から出たのは、予算だから数字が違っているのかなという確認。それから、もう一度、区としての支出の総額の確認だけ教えてください。","respondent":"桑村人事課長","answer":"一つは、この間、ご報告申し上げましたのは、人事委員会の考え方で、２３区の平均給与ということで考えた数字です。それから、広報に載せたのは、まさに予算の、区の職員の考え方ですので、基本的に言うと、決算で考えるのが一番いいのかなと思ってあります。","voiceIndex":9,"id":"exchange-003"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1706#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2005-01-01&TermEnd=2005-12-31"}],"sourceMeta":{"pages":0,"characters":4008,"voices":20}}]);
